package com.toadfx.tithefarmautopilot;

import com.toadfx.tithefarmautopilot.logic.Goal;
import com.toadfx.tithefarmautopilot.logic.PlayStyle;
import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup(TitheFarmAutopilotConfig.GROUP)
public interface TitheFarmAutopilotConfig extends Config
{
	String GROUP = "tithefarmautopilot";

	@ConfigSection(name = "Play style", description = "How many plants and how hard you want to work", position = 0)
	String styleSection = "style";

	@ConfigSection(name = "Overlays", description = "What to show in the game", position = 1)
	String overlaySection = "overlays";

	@ConfigSection(name = "Alerts", description = "Notifications and chat messages", position = 2)
	String alertSection = "alerts";

	@ConfigSection(name = "Colours", description = "Overlay colours", position = 3, closedByDefault = true)
	String colourSection = "colours";

	@ConfigSection(name = "Side panel", description = "Side panel options", position = 4)
	String panelSection = "sidePanel";

	// ---------------------------------------------------------------- style

	@ConfigItem(keyName = "playStyle", name = "Play style", position = 0, section = styleSection,
		description = "Chill, Steady and Fertiliser for learning; Combo 20, 23x, 24x, 25x easy, 25x4, 25x recursive, 24x combo and Staggered are the wiki's advanced routes")
	default PlayStyle playStyle()
	{
		return PlayStyle.STEADY;
	}

	@Range(min = 8, max = 12)
	@ConfigItem(keyName = "chillPlants", name = "Chill plants", position = 1, section = styleSection,
		description = "Plants per lap in the Chill style (8-12)")
	default int chillPlants()
	{
		return 10;
	}

	@ConfigItem(keyName = "steadyCutoff16", name = "Steady: stop at 16", position = 2, section = styleSection,
		description = "Plant 16 instead of 20 in the Steady style (the wiki's cutoff)")
	default boolean steadyCutoff16()
	{
		return false;
	}

	@ConfigItem(keyName = "goal", name = "Points goal", position = 3, section = styleSection,
		description = "What you're saving Tithe points for. 'Rewards planner' follows the side panel's planner: the next reward you don't own.")
	default Goal goal()
	{
		return Goal.REWARDS_PLANNER;
	}

	@ConfigItem(keyName = "outfitReminder", name = "Outfit swap reminder", position = 4, section = styleSection,
		description = "Remind you to put the farmer's outfit on before harvesting and depositing (wear light gear while planting)")
	default boolean outfitReminder()
	{
		return true;
	}

	@ConfigItem(keyName = "barehandedPlanting", name = "I have Barehanded planting", position = 5, section = styleSection,
		description = "Tick this if you've unlocked planting without a seed dibber, so it stops asking for one")
	default boolean barehandedPlanting()
	{
		return false;
	}

	// ---------------------------------------------------------------- overlays

	@ConfigItem(keyName = "showStep", name = "Next step box", position = 0, section = overlaySection,
		description = "Show the next step at the top of the screen")
	default boolean showStep()
	{
		return true;
	}

	@ConfigItem(keyName = "highlightTarget", name = "Highlight next patch", position = 1, section = overlaySection,
		description = "Outline the patch your next step is on")
	default boolean highlightTarget()
	{
		return true;
	}

	@ConfigItem(keyName = "highlightItems", name = "Highlight items", position = 1, section = overlaySection,
		description = "Outline the item the step needs in your inventory: fertiliser, seeds or a watering can")
	default boolean highlightItems()
	{
		return true;
	}

	@ConfigItem(keyName = "showNumbers", name = "Route numbers", position = 2, section = overlaySection,
		description = "Number every patch on your route")
	default boolean showNumbers()
	{
		return true;
	}

	@ConfigItem(keyName = "showTimers", name = "Plant timers", position = 3, section = overlaySection,
		description = "A timer pie on each growing plant (turn off the core Tithe Farm plugin to avoid two)")
	default boolean showTimers()
	{
		return true;
	}

	@ConfigItem(keyName = "outlineRoute", name = "Outline route patches", position = 4, section = overlaySection,
		description = "Colour every route patch by what it needs (plant, water, harvest)")
	default boolean outlineRoute()
	{
		return true;
	}

	@ConfigItem(keyName = "showSession", name = "Session box", position = 5, section = overlaySection,
		description = "Fruit in the sack, points, goal, XP and laps")
	default boolean showSession()
	{
		return true;
	}

	@ConfigItem(keyName = "dangerFlash", name = "Red flash when a plant is dying", position = 6, section = overlaySection,
		description = "Tint the screen red while a dry plant has under 12 seconds left")
	default boolean dangerFlash()
	{
		return true;
	}

	// ---------------------------------------------------------------- alerts

	@ConfigItem(keyName = "notifyDying", name = "Notify: plant dying", position = 0, section = alertSection,
		description = "Notify when a dry plant has under 12 seconds left")
	default boolean notifyDying()
	{
		return true;
	}

	@ConfigItem(keyName = "notifyGrown", name = "Notify: lap grown", position = 1, section = alertSection,
		description = "Notify when every plant on the route is ready to harvest")
	default boolean notifyGrown()
	{
		return false;
	}

	@ConfigItem(keyName = "notifyGoal", name = "Notify: goal reached", position = 2, section = alertSection,
		description = "Notify when you have enough points for your goal")
	default boolean notifyGoal()
	{
		return true;
	}

	@ConfigItem(keyName = "chatLapSummary", name = "Lap report in chat", position = 3, section = alertSection,
		description = "Post the lap's grade, time and tip in chat")
	default boolean chatLapSummary()
	{
		return true;
	}

	// ---------------------------------------------------------------- colours

	@Alpha
	@ConfigItem(keyName = "targetColor", name = "Next patch", position = 0, section = colourSection, description = "")
	default Color targetColor()
	{
		return new Color(0xFF00F1);
	}

	@Alpha
	@ConfigItem(keyName = "plantColor", name = "Plant", position = 1, section = colourSection, description = "Empty patches waiting to be planted")
	default Color plantColor()
	{
		return new Color(0xFF7300);
	}

	@Alpha
	@ConfigItem(keyName = "waterColor", name = "Needs water", position = 2, section = colourSection, description = "")
	default Color waterColor()
	{
		return new Color(0xFFEB00);
	}

	@Alpha
	@ConfigItem(keyName = "wetColor", name = "Watered", position = 3, section = colourSection, description = "")
	default Color wetColor()
	{
		return new Color(0x3FA9F5);
	}

	@Alpha
	@ConfigItem(keyName = "harvestColor", name = "Harvest", position = 4, section = colourSection, description = "")
	default Color harvestColor()
	{
		return new Color(0x00E676);
	}

	@Alpha
	@ConfigItem(keyName = "dangerColor", name = "Danger", position = 5, section = colourSection, description = "Dying and dead plants")
	default Color dangerColor()
	{
		return new Color(0xFF1E1E);
	}

	@Alpha
	@ConfigItem(keyName = "flashColor", name = "Red flash", position = 6, section = colourSection, description = "")
	default Color flashColor()
	{
		return new Color(255, 30, 30, 70);
	}

	@ConfigItem(keyName = "showSocials", name = "Show channel buttons", position = 0, section = panelSection,
		description = "ToadFx's channel buttons at the bottom of the side panel (needs a plugin restart)")
	default boolean showSocials()
	{
		return true;
	}
}

package com.toadfx.tithefarmautopilot;

import com.google.inject.Provides;
import com.toadfx.tithefarmautopilot.coach.Grader;
