@PluginDescriptor(
	name = "Tithe Farm Autopilot",
	description = "Tithe Farm: next patch to plant, water or harvest, route numbers, plant timers, points goal and a grade for every lap",
	tags = {"tithe", "farm", "farming", "minigame", "hosidius", "skilling", "guide", "route", "timers", "points", "golovanova", "bologano", "logavano"}
)
public class TitheFarmAutopilotPlugin extends Plugin
{
	private static final String KEY_HISTORY = "history";
	private static final String KEY_ORDER = "rewardOrder";
	private static final String KEY_OWNED = "rewardsOwned";
	private static final int HISTORY_MAX = 40;
	private static final Color CHAT = new Color(0xB0, 0x00, 0xA6);

	@Inject
	private Client client;

	@Inject
	private TitheFarmAutopilotConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ClientThread clientThread;

	@Inject
	private Notifier notifier;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private StepOverlay stepOverlay;

	@Inject
	private SceneOverlay sceneOverlay;

	@Inject
	private SessionOverlay sessionOverlay;

	@Inject
	private DangerFlashOverlay dangerFlashOverlay;

	@Inject
	private InventoryOverlay inventoryOverlay;

	private TitheFarmAutopilotPanel panel;
	private NavigationButton navButton;

	private volatile Farm farm = new Farm(PlayStyle.STEADY, 20);
	private volatile Instruction instruction = Instruction.NONE;
	private volatile boolean inFarm;
	private volatile boolean nearFarm;
	private volatile int score = -1;
	private volatile int points = -1;
	private volatile int water;

	/** Every patch object in the scene by region tile, so the route can be rebuilt after a style change. */
	private final Map<Integer, GameObject> scenePlots = new HashMap<>();
	/** Patch object for each route index (null if not loaded). */
	private volatile GameObject[] routeObjects = new GameObject[Route.MAX];

	private final Snapshot snap = new Snapshot();
	private volatile int herblore = -1;
	private volatile int farmingBoosted = -1;
	private volatile int farmingReal = -1;

	// Rewards planner (saved per RuneScape account)
	private volatile List<Reward> rewardOrder = RewardPlan.DEFAULT_ORDER;
	private final Set<Reward> owned = Collections.synchronizedSet(EnumSet.noneOf(Reward.class));
	private int lastGoalTarget = -1;
	private volatile List<RewardPlan.Row> rewardPlan = Collections.emptyList();

	// Things to point at: the seed table, the sack and the water barrels.
	private volatile GameObject seedTable;
	private volatile GameObject sack;
	private final List<GameObject> barrels = Collections.synchronizedList(new ArrayList<>());
	private boolean hasDibber;
	private final Session session = new Session();
	private final List<LapRecord> history = Collections.synchronizedList(new ArrayList<>());
	private volatile LapRecord lastLap;
	private boolean historyLoaded;

	// Alert bookkeeping
	private final Set<Integer> warnedDying = new HashSet<>();
	private boolean warnedGrown;
	private boolean warnedGoal;
	private int lastFarmingXp = -1;
	private int panelTick;

	@Provides
	TitheFarmAutopilotConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(TitheFarmAutopilotConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(sceneOverlay);
		overlayManager.add(stepOverlay);
		overlayManager.add(sessionOverlay);
		overlayManager.add(dangerFlashOverlay);
		overlayManager.add(inventoryOverlay);

		BufferedImage logo = ImageUtil.loadImageResource(TitheFarmAutopilotPlugin.class, "panel_logo.png");
		BufferedImage icon = ImageUtil.loadImageResource(TitheFarmAutopilotPlugin.class, "panel_icon.png");
		panel = new TitheFarmAutopilotPanel(this, config, configManager, logo);
		navButton = NavigationButton.builder()
			.tooltip("Tithe Farm Autopilot")
			.icon(icon)
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		historyLoaded = false;

		// Game state belongs to the client thread. If the plugin is turned on mid-session, load the
		// saved laps and planner and pick up the patches already in the scene.
		clientThread.invokeLater(() ->
		{
			rebuildRoute();
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				loadHistory();
				scanScene();
			}
		});
	}

	/** Finds patches, the seed table, the sack and barrels that were loaded before the plugin started. */
	private void scanScene()
	{
		WorldView wv = client.getTopLevelWorldView();
		Scene scene = wv.getScene();
		if (scene == null)
		{
			return;
		}
		Tile[][] plane = scene.getTiles()[wv.getPlane()];
		for (Tile[] column : plane)
		{
			for (Tile tile : column)
			{
				if (tile == null)
				{
					continue;
				}
				for (GameObject obj : tile.getGameObjects())
				{
					// A 3x3 patch sits on 9 tiles: handle it once, from its south-west tile.
					if (obj != null && obj.getSceneMinLocation().equals(tile.getSceneLocation()))
					{
						onSpawn(obj);
					}
				}
			}
		}
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(sceneOverlay);
		overlayManager.remove(stepOverlay);
		overlayManager.remove(sessionOverlay);
		overlayManager.remove(dangerFlashOverlay);
		overlayManager.remove(inventoryOverlay);
		clientToolbar.removeNavigation(navButton);
		navButton = null;
		panel = null;
		instruction = Instruction.NONE;
		inFarm = false;
		nearFarm = false;
		clientThread.invoke(() ->
		{
			scenePlots.clear();
			routeObjects = new GameObject[Route.MAX];
			seedTable = null;
			sack = null;
			barrels.clear();
			farm.clear();
			lastFarmingXp = -1;
		});
	}

	// ------------------------------------------------------------------ events

	@Subscribe
	public void onGameStateChanged(GameStateChanged e)
	{
		GameState s = e.getGameState();
		if (s == GameState.LOADING || s == GameState.HOPPING || s == GameState.LOGIN_SCREEN)
		{
			scenePlots.clear();
			routeObjects = new GameObject[Route.MAX];
			seedTable = null;
			sack = null;
			barrels.clear();
		}
		if (s == GameState.LOGIN_SCREEN || s == GameState.HOPPING)
		{
			// Logging out wipes the plants.
			farm.clear();
			lastFarmingXp = -1;
		}
		if (s == GameState.LOGGED_IN && !historyLoaded)
		{
			loadHistory();
		}
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned e)
	{
		onSpawn(e.getGameObject());
	}

	private void onSpawn(GameObject obj)
	{
		int id = obj.getId();
		if (PlotIds.isPlot(id))
		{
			track(obj);
		}
		else if (id == Ids.SEED_TABLE)
		{
			seedTable = obj;
		}
		else if (id == Ids.SACK || id == Ids.SACK_EMPTY)
		{
			sack = obj;
		}
		else if (Ids.isBarrel(id) && !barrels.contains(obj))
		{
			barrels.add(obj);
		}
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned e)
	{
		GameObject obj = e.getGameObject();
		if (obj == seedTable)
		{
			seedTable = null;
		}
		if (obj == sack)
		{
			sack = null;
		}
		barrels.remove(obj);
		if (!PlotIds.isPlot(obj.getId()))
		{
			return;
		}
		scenePlots.values().removeIf(o -> o == obj);
		GameObject[] objs = routeObjects;
		for (int i = 0; i < objs.length; i++)
		{
			if (objs[i] == obj)
			{
				objs[i] = null;
			}
		}
	}

	/**
	 * Spots "Use Gricoller's fertiliser -> plant" so the patch's timer switches to half speed. The
	 * game shows no change on the plant, so this click is the only sign.
	 */
	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked e)
	{
		if (!inFarm || !PlotIds.isPlot(e.getId()) || !"Use".equals(Text.removeTags(e.getMenuOption())))
		{
			return;
		}
		String target = Text.removeTags(e.getMenuTarget()).toLowerCase();
		if (!target.contains("fertiliser") || target.contains("compost"))
		{
			return;
		}
		int sx = e.getParam0();
		int sy = e.getParam1();
		GameObject[] objs = routeObjects;
		for (int i = 0; i < objs.length && i < farm.size(); i++)
		{
			GameObject o = objs[i];
			if (o != null && o.getSceneMinLocation().getX() == sx && o.getSceneMinLocation().getY() == sy)
			{
				farm.getRoute().get(i).markFertilised(client.getTickCount());
				return;
			}
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged e)
	{
		int id = e.getContainerId();
		if (id == InventoryID.INV)
		{
			readInventory(e.getItemContainer());
		}
		if (id == InventoryID.INV || id == InventoryID.WORN || id == InventoryID.BANK)
		{
			findOwnedRewards(e.getItemContainer());
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged e)
	{
		if (e.getSkill() != Skill.FARMING)
		{
			return;
		}
		int xp = e.getXp();
		if (lastFarmingXp >= 0 && inFarm && xp > lastFarmingXp)
		{
			session.start(System.currentTimeMillis());
			session.addXp(xp - lastFarmingXp);
		}
		lastFarmingXp = xp;
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged e)
	{
		if (!TitheFarmAutopilotConfig.GROUP.equals(e.getGroup()))
		{
			return;
		}
		String key = e.getKey();
		if ("playStyle".equals(key) || "chillPlants".equals(key) || "steadyCutoff16".equals(key))
		{
			// Config can change on the Swing thread (side panel); the scene belongs to the client thread.
			clientThread.invokeLater(this::rebuildRoute);
		}
		if ("goal".equals(key))
		{
			warnedGoal = false;
		}
		refreshPanel();
	}

	@Subscribe
	public void onGameTick(GameTick e)
	{
		boolean wasInFarm = inFarm;
		updateLocation();
		int tick = client.getTickCount();

		if (nearFarm)
		{
			score = client.getVarbitValue(Ids.SCORE_VARBIT);
			points = client.getVarbitValue(Ids.POINTS_VARBIT);
			session.setPoints(points);
		}
		if (wasInFarm && !inFarm)
		{
			// Left the farm: the instance and its plants are gone.
			farm.clear();
		}

		farmingBoosted = client.getBoostedSkillLevel(Skill.FARMING);
		farmingReal = client.getRealSkillLevel(Skill.FARMING);
		herblore = client.getRealSkillLevel(Skill.HERBLORE);
		snap.farmingLevel = farmingBoosted;
		snap.realFarmingLevel = farmingReal;
		snap.inFarm = inFarm;
		// Barehanded planting can't be read from the game, so it's a setting.
		snap.canPlant = hasDibber || config.barehandedPlanting();
		snap.tick = tick;
		int charges = snap.hasGricollerCan ? Math.max(0, client.getVarbitValue(Ids.GRICOLLER_CHARGES_VARBIT)) : 0;
		water = snap.cansWater + charges;
		snap.water = water;

		instruction = nearFarm ? Planner.next(farm.getRoute(), farm.getCursor(), snap, config.playStyle(), config.outfitReminder())
			: Instruction.NONE;

		updateRewardPlan();
		Farm.Lap lap = farm.takeFinishedLap();
		if (lap != null)
		{
			onLapEnd(lap);
		}
		alerts(tick);

		if (++panelTick % 2 == 0)
		{
			refreshPanel();
		}
	}

	// ------------------------------------------------------------------ tracking

	private void track(GameObject obj)
	{
		WorldPoint t = WorldPoint.fromLocalInstance(client, obj.getLocalLocation());
		if (t == null || t.getRegionID() != Route.REGION)
		{
			return;
		}
		scenePlots.put(key(t.getRegionX(), t.getRegionY()), obj);
		apply(obj, t.getRegionX(), t.getRegionY(), client.getTickCount());
	}

	private void apply(GameObject obj, int rx, int ry, int tick)
	{
		Plot p = farm.at(rx, ry);
		if (p == null)
		{
			return;
		}
		routeObjects[p.index] = obj;
		PlotIds.Decoded d = PlotIds.decode(obj.getId());
		if (d == null)
		{
			return;
		}
		Plot.Change c = farm.apply(p, d.kind, d.stage, tick);
		switch (c)
		{
			case PLANTED:
				session.start(System.currentTimeMillis());
				warnedGrown = false;
				break;
			case HARVESTED:
				session.addHarvest(1);
				break;
			case DIED:
				session.addDeath();
				break;
			default:
				break;
		}
	}

	private void rebuildRoute()
	{
		PlayStyle style = config.playStyle();
		int plants = style.plants(config.chillPlants(), config.steadyCutoff16());
		Farm f = new Farm(style, plants);
		farm = f;
		routeObjects = new GameObject[Route.MAX];
		int tick = client.getTickCount();
		for (Map.Entry<Integer, GameObject> en : scenePlots.entrySet())
		{
			int k = en.getKey();
			apply(en.getValue(), k / 1000, k % 1000, tick);
		}
		f.takeFinishedLap();
		warnedDying.clear();
	}

	private static int key(int rx, int ry)
	{
		return rx * 1000 + ry;
	}

	private void updateLocation()
	{
		Player me = client.getLocalPlayer();
		if (me == null)
		{
			nearFarm = false;
			inFarm = false;
			return;
		}
		WorldPoint t = WorldPoint.fromLocalInstance(client, me.getLocalLocation());
		nearFarm = t != null && t.getRegionID() == Route.REGION;
		inFarm = nearFarm && client.getTopLevelWorldView().isInstance();
	}

	private void readInventory(ItemContainer inv)
	{
		int seeds = 0;
		int seedTier = -1;
		int fruit = 0;
		int cansWater = 0;
		int cans = 0;
		boolean dibber = false;
		boolean spade = false;
		boolean outfit = false;
		boolean fertiliser = false;
		boolean gricoller = false;
		for (Item item : inv.getItems())
		{
			int id = item.getId();
			if (id <= 0)
			{
				continue;
			}
			if (Ids.seedIndex(Ids.SEEDS, id) >= 0)
			{
				seeds += item.getQuantity();
				seedTier = Math.max(seedTier, Ids.seedIndex(Ids.SEEDS, id));
			}
			else if (Ids.seedIndex(Ids.FRUIT, id) >= 0)
			{
				fruit += item.getQuantity();
			}
			else if (Ids.cansDoses(id) >= 0)
			{
				cans++;
				cansWater += Ids.cansDoses(id);
			}
			else if (id == Ids.GRICOLLER_CAN)
			{
				gricoller = true;
			}
			else if (id == Ids.DIBBER)
			{
				dibber = true;
			}
			else if (id == Ids.SPADE)
			{
				spade = true;
			}
			else if (id == Ids.FERTILISER)
			{
				fertiliser = true;
			}
			else if (Ids.isOutfit(id))
			{
				outfit = true;
			}
		}
		snap.seeds = seeds;
		snap.seedTier = seedTier;
		snap.fruit = fruit;
		snap.cansWater = cansWater;
		snap.cans = cans;
		snap.hasGricollerCan = gricoller;
		hasDibber = dibber;
		snap.hasSpade = spade;
		snap.outfitInInventory = outfit;
		snap.hasFertiliser = fertiliser;
	}

	// ------------------------------------------------------------------ laps and alerts

	private void onLapEnd(Farm.Lap lap)
	{
		PlayStyle style = config.playStyle();
		int plants = Math.max(lap.planted, 1);
		boolean fert = style.usesFertiliser();
		int secs = lap.seconds();
		String grade = Grader.grade(plants, lap.harvested, lap.deaths, secs, fert);
		String tip = Grader.tip(plants, lap.harvested, lap.deaths, secs, fert, Route.MAX);
		LapRecord rec = new LapRecord(System.currentTimeMillis(), style.shortName(), plants, lap.harvested, lap.deaths, secs, grade, tip);
		lastLap = rec;
		session.addLap(rec);
		history.add(rec);
		while (history.size() > HISTORY_MAX)
		{
			history.remove(0);
		}
		saveHistory();
		warnedDying.clear();
		warnedGrown = false;
		if (config.chatLapSummary())
		{
			chat("Lap " + session.getLaps() + ": grade " + grade + " in " + rec.time()
				+ " (" + lap.harvested + "/" + plants + " harvested). " + tip);
		}
	}

	private void alerts(int tick)
	{
		if (!inFarm)
		{
			return;
		}
		if (config.notifyDying() && instruction.getUrgency() == Urgency.NOW && instruction.getTarget() >= 0)
		{
			Plot p = farm.getRoute().get(instruction.getTarget());
			int k = p.index * 10 + p.getStage();
			if (warnedDying.add(k))
			{
				notifier.notify("Tithe Farm: water patch " + p.label() + " now!");
			}
		}
		if (config.notifyGrown() && !warnedGrown && farm.isLapRunning())
		{
			boolean allGrown = true;
			for (Plot p : farm.getRoute())
			{
				if (p.getKind() != PlotKind.GROWN && p.getKind() != PlotKind.EMPTY)
				{
					allGrown = false;
					break;
				}
			}
			if (allGrown)
			{
				warnedGrown = true;
				notifier.notify("Tithe Farm: everything is grown, time to harvest");
			}
		}
		int goal = getGoalTarget();
		if (goal != lastGoalTarget)
		{
			lastGoalTarget = goal;
			warnedGoal = false;
		}
		if (config.notifyGoal() && !warnedGoal && goal > 0 && points >= goal && session.getPoints() > 0)
		{
			warnedGoal = true;
			notifier.notify("Tithe Farm: you have " + points + " points, enough for " + getGoalName());
			chat("Goal reached: " + getGoalName() + ". Spend it at Farmer Gricoller.");
		}
	}

	private void chat(String text)
	{
		String msg = new ChatMessageBuilder()
			.append(CHAT, "[Tithe Farm Autopilot] ")
			.append(text)
			.build();
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage(msg)
			.build());
	}

	// ------------------------------------------------------------------ history

	private void loadHistory()
	{
		String raw = configManager.getRSProfileConfiguration(TitheFarmAutopilotConfig.GROUP, KEY_HISTORY);
		history.clear();
		if (raw != null && !raw.isEmpty())
		{
			for (String line : raw.split("\n"))
			{
				LapRecord r = LapRecord.decode(line);
				if (r != null)
				{
					history.add(r);
				}
			}
		}
		lastLap = history.isEmpty() ? null : history.get(history.size() - 1);
		rewardOrder = RewardPlan.decodeOrder(configManager.getRSProfileConfiguration(TitheFarmAutopilotConfig.GROUP, KEY_ORDER));
		synchronized (owned)
		{
			owned.clear();
			owned.addAll(RewardPlan.decodeOwned(configManager.getRSProfileConfiguration(TitheFarmAutopilotConfig.GROUP, KEY_OWNED)));
		}
		historyLoaded = configManager.getRSProfileKey() != null;
	}

	private void saveHistory()
	{
		StringBuilder sb = new StringBuilder();
		synchronized (history)
		{
			for (LapRecord r : history)
			{
				if (sb.length() > 0)
				{
					sb.append('\n');
				}
				sb.append(r.encode());
			}
		}
		configManager.setRSProfileConfiguration(TitheFarmAutopilotConfig.GROUP, KEY_HISTORY, sb.toString());
	}

