	// ------------------------------------------------------------------ rewards planner

	private void findOwnedRewards(ItemContainer c)
	{
		List<Reward> found = new ArrayList<>();
		for (Item item : c.getItems())
		{
			Reward r = Ids.rewardFor(item.getId());
			if (r != null && !owned.contains(r) && !found.contains(r))
			{
				found.add(r);
			}
		}
		if (found.isEmpty())
		{
			return;
		}
		owned.addAll(found);
		saveRewards();
		for (Reward r : found)
		{
			chat("Rewards planner: marked " + r.displayName() + " as owned.");
		}
		refreshPanel();
	}

	/** Ticks a reward on or off by hand (auto-weed can't be seen, and items can be dropped). */
	public void toggleOwned(Reward r)
	{
		clientThread.invoke(() ->
		{
			if (!owned.remove(r))
			{
				owned.add(r);
			}
			saveRewards();
			updateRewardPlan();
			refreshPanel();
		});
	}

	public void moveRewardUp(Reward r)
	{
		clientThread.invoke(() ->
		{
			rewardOrder = RewardPlan.moveUp(rewardOrder, r);
			saveRewards();
			updateRewardPlan();
			refreshPanel();
		});
	}

	public void resetRewardOrder()
	{
		clientThread.invoke(() ->
		{
			rewardOrder = RewardPlan.DEFAULT_ORDER;
			saveRewards();
			updateRewardPlan();
			refreshPanel();
		});
	}

	private void saveRewards()
	{
		if (configManager.getRSProfileKey() == null)
		{
			return;
		}
		configManager.setRSProfileConfiguration(TitheFarmAutopilotConfig.GROUP, KEY_ORDER, RewardPlan.encodeOrder(rewardOrder));
		synchronized (owned)
		{
			configManager.setRSProfileConfiguration(TitheFarmAutopilotConfig.GROUP, KEY_OWNED, RewardPlan.encodeOwned(owned));
		}
	}

	/** Your points rate: this session's once you've done a lap, else estimated from your laps or the style's target. */
	public double getPointsPerHour()
	{
		long now = System.currentTimeMillis();
		if (session.getLaps() >= 1 && session.perHour(session.getPoints(), now) > 0)
		{
			return session.perHour(session.getPoints(), now);
		}
		PlayStyle style = config.playStyle();
		int plants = farm.size();
		int total = 0;
		int count = 0;
		for (LapRecord r : getHistory())
		{
			if (r.style.equals(style.shortName()) && r.plants == plants && r.deaths == 0)
			{
				total += r.seconds;
				count++;
			}
		}
		int lapSecs = count > 0 ? total / count : Grader.targetSeconds(plants, style.usesFertiliser()) + 20;
		return RewardPlan.estimatePointsPerHour(plants, lapSecs);
	}

