	private GameObject nearestBarrel()
	{
		Player me = client.getLocalPlayer();
		if (me == null)
		{
			return null;
		}
		GameObject best = null;
		int bestDist = Integer.MAX_VALUE;
		synchronized (barrels)
		{
			for (GameObject b : barrels)
			{
				int d = b.getLocalLocation().distanceTo(me.getLocalLocation());
				if (d < bestDist)
				{
					bestDist = d;
					best = b;
				}
			}
		}
		return best;
	}

