package com.toadfx.tithefarmautopilot.coach;

/**
 * Grades a lap S to F on two things: plants lost and lap time against a target.
 *
 * <p>Target = growth time (3 stages) + about 3 seconds per plant to plant, water and harvest,
 * + 15 seconds to deposit and refill. 20 plants unfertilised: 180 + 60 + 15 = 255 s.
 */
public final class Grader
{
	private Grader()
	{
	}

	public static int targetSeconds(int plants, boolean fertiliser)
	{
		int growth = fertiliser ? 90 : 180;
		return growth + 3 * plants + 15;
	}

	public static String grade(int plants, int harvested, int deaths, int seconds, boolean fertiliser)
	{
		if (plants <= 0)
		{
			return "-";
		}
		if (deaths * 4 >= plants || harvested == 0)
		{
			return "F";
		}
		double pace = targetSeconds(plants, fertiliser) / (double) Math.max(1, seconds);
		String g;
		if (pace >= 1.0)
		{
			g = "S";
		}
		else if (pace >= 0.9)
		{
			g = "A";
		}
		else if (pace >= 0.8)
		{
			g = "B";
		}
		else if (pace >= 0.65)
		{
			g = "C";
		}
		else
		{
			g = "D";
		}
		// Each dead plant drops a grade.
		String order = "SABCDF";
		int idx = Math.min(order.length() - 1, order.indexOf(g) + deaths);
		return String.valueOf(order.charAt(idx));
	}

	public static String tip(int plants, int harvested, int deaths, int seconds, boolean fertiliser, int maxPlants)
	{
		if (deaths > 0)
		{
			return deaths == 1 ? "1 plant died. Water as soon as a patch turns dry; the step box goes red with 12s left."
				: deaths + " plants died. Try fewer plants until the route feels easy.";
		}
		int target = targetSeconds(plants, fertiliser);
		if (seconds > target * 1.25)
		{
			return "Slow lap. Deposit and refill during the last wait (grown plants can't die).";
		}
		if (seconds > target)
		{
			return "Water right after planting to skip the dibber animation, and cut corners diagonally.";
		}
		if (plants < maxPlants)
		{
			return "Clean lap! Ready for more plants: try the next style up.";
		}
		return "Clean lap. Keep it up.";
	}
}

package com.toadfx.tithefarmautopilot.coach;

/** One finished lap: plant everything, grow, harvest. */
public final class LapRecord
{
	public final long endedAt;
	public final String style;
	public final int plants;
	public final int harvested;
	public final int deaths;
	public final int seconds;
	public final String grade;
	public final String tip;

	public LapRecord(long endedAt, String style, int plants, int harvested, int deaths, int seconds, String grade, String tip)
	{
		this.endedAt = endedAt;
		this.style = style;
		this.plants = plants;
		this.harvested = harvested;
		this.deaths = deaths;
		this.seconds = seconds;
		this.grade = grade;
		this.tip = tip;
	}

	public String time()
	{
		return seconds / 60 + ":" + (seconds % 60 < 10 ? "0" : "") + seconds % 60;
	}

	/** Compact form for saving in the config: fields joined by '|'. */
	public String encode()
	{
		return endedAt + "|" + style.replace("|", "") + "|" + plants + "|" + harvested + "|" + deaths + "|" + seconds + "|" + grade + "|" + tip.replace("|", "");
	}

	public static LapRecord decode(String s)
	{
		try
		{
			String[] f = s.split("\\|", -1);
			return new LapRecord(Long.parseLong(f[0]), f[1], Integer.parseInt(f[2]), Integer.parseInt(f[3]),
				Integer.parseInt(f[4]), Integer.parseInt(f[5]), f[6], f.length > 7 ? f[7] : "");
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}
}

package com.toadfx.tithefarmautopilot.coach;

/** Totals since you entered the farm (or pressed reset). */
public final class Session
{
	private long startedAt;
	private int laps;
	private int harvested;
	private int deaths;
	private int xp;
	private int pointsAtStart = -1;
	private int points;
	private int bestLapSeconds;

	public void reset(long now)
	{
		startedAt = now;
		laps = 0;
		harvested = 0;
		deaths = 0;
		xp = 0;
		pointsAtStart = -1;
		points = 0;
		bestLapSeconds = 0;
	}

	public boolean isStarted()
	{
		return startedAt > 0;
	}

	public void start(long now)
	{
		if (startedAt == 0)
		{
			startedAt = now;
		}
	}

	public void addLap(LapRecord lap)
	{
		laps++;
		if (lap.deaths == 0 && (bestLapSeconds == 0 || lap.seconds < bestLapSeconds))
		{
			bestLapSeconds = lap.seconds;
		}
	}

	public void addHarvest(int n)
	{
		harvested += n;
	}

	public void addDeath()
	{
		deaths++;
	}

	public void addXp(int gained)
	{
		if (gained > 0 && gained < 100_000)
		{
			xp += gained;
		}
	}

	public void setPoints(int current)
	{
		if (current < 0)
		{
			return;
		}
		if (pointsAtStart < 0)
		{
			pointsAtStart = current;
		}
		points = Math.max(0, current - pointsAtStart);
	}

	public double hours(long now)
	{
		return startedAt == 0 ? 0 : Math.max(1, now - startedAt) / 3_600_000.0;
	}

	public int perHour(int value, long now)
	{
		double h = hours(now);
		// Wait a minute before showing rates, they jump around at first.
		return h < 1 / 60.0 ? 0 : (int) Math.round(value / h);
	}

	public int getLaps()
	{
		return laps;
	}

	public int getHarvested()
	{
		return harvested;
	}

	public int getDeaths()
	{
		return deaths;
	}

	public int getXp()
	{
		return xp;
	}

	public int getPoints()
	{
		return points;
	}

	public int getBestLapSeconds()
	{
		return bestLapSeconds;
	}

	public long getStartedAt()
	{
		return startedAt;
	}
}

