package com.toadfx.tithefarmautopilot.logic;

import java.util.List;

/**
 * The route's patches plus lap bookkeeping: where you are on the route and when a lap starts and
 * ends. Pure logic; the plugin feeds it patch changes.
 */
public final class Farm
{
	private List<Plot> route;
	private int[] coords;
	private boolean continuous;
	private int cursor = -1;

	private boolean lapRunning;
	private int lapStartTick;
	private int lapPlanted;
	private int lapHarvested;
	private int lapDeaths;
	private Lap finished;

	public Farm(PlayStyle style, int plants)
	{
		coords = style.route();
		continuous = style.isContinuous();
		route = Route.build(coords, plants);
		cursor = -1;
		lapRunning = false;
		finished = null;
	}

	public List<Plot> getRoute()
	{
		return route;
	}

	public int getCursor()
	{
		return cursor;
	}

	public int size()
	{
		return route.size();
	}

	/** Patch at this region tile on the route, or null. */
	public Plot at(int regionX, int regionY)
	{
		int i = Route.indexOf(coords, regionX, regionY, route.size());
		return i < 0 ? null : route.get(i);
	}

	/** Records a patch's look. Returns what changed. */
	public Plot.Change apply(Plot p, PlotKind kind, int stage, int tick)
	{
		Plot.Change c = p.update(kind, stage, tick);
		switch (c)
		{
			case PLANTED:
				if (!lapRunning)
				{
					lapRunning = true;
					lapStartTick = tick;
					lapPlanted = 0;
					lapHarvested = 0;
					lapDeaths = 0;
				}
				lapPlanted++;
				cursor = p.index;
				break;
			case WATERED:
			case CLEARED:
				cursor = p.index;
				break;
			case HARVESTED:
				cursor = p.index;
				lapHarvested++;
				if (continuous && lapRunning && lapHarvested >= route.size())
				{
					// Combo and staggered never empty the farm: count a lap every N harvests.
					finished = new Lap(lapHarvested, lapHarvested, lapDeaths, tick - lapStartTick);
					lapStartTick = tick;
					lapPlanted = 0;
					lapHarvested = 0;
					lapDeaths = 0;
				}
				break;
			case DIED:
				lapDeaths++;
				break;
			default:
				break;
		}
		if (c == Plot.Change.HARVESTED || c == Plot.Change.CLEARED)
		{
			checkLapEnd(tick);
		}
		return c;
	}

	private void checkLapEnd(int tick)
	{
		for (Plot p : route)
		{
			if (p.getKind() != PlotKind.EMPTY)
			{
				return;
			}
		}
		cursor = -1;
		if (lapRunning && (finished != null || lapPlanted + lapHarvested == 0))
		{
			lapRunning = false;
		}
		else if (lapRunning)
		{
			lapRunning = false;
			finished = new Lap(lapPlanted, lapHarvested, lapDeaths, tick - lapStartTick);
		}
	}

	/** A lap that just ended, once. */
	public Lap takeFinishedLap()
	{
		Lap l = finished;
		finished = null;
		return l;
	}

	public boolean isLapRunning()
	{
		return lapRunning;
	}

	public int getLapPlanted()
	{
		return lapPlanted;
	}

	public int getLapDeaths()
	{
		return lapDeaths;
	}

	public int lapTicks(int tick)
	{
		return lapRunning ? tick - lapStartTick : 0;
	}

	/** Forget every patch (left the farm or logged out: the plants are gone). */
	public void clear()
	{
		for (Plot p : route)
		{
			p.forget();
		}
		cursor = -1;
		lapRunning = false;
		finished = null;
	}

	public static final class Lap
	{
		public final int planted;
		public final int harvested;
		public final int deaths;
		public final int ticks;

		Lap(int planted, int harvested, int deaths, int ticks)
		{
			this.planted = planted;
			this.harvested = harvested;
			this.deaths = deaths;
			this.ticks = ticks;
		}

		public int seconds()
		{
			return (int) Math.round(ticks * 0.6);
		}
	}
}

