package com.toadfx.tithefarmautopilot.logic;

import java.util.List;

/**
 * Picks the next step. Pure logic, no RuneLite, so it can be tested.
 *
 * <p>The idea is the wiki's basic method: walk the route in order. Lap 1 plants and waters every
 * patch, the next two laps water each one, the last lap harvests, then deposit and refill. Rather
 * than track laps, it looks for the next patch along the route (after the last one you worked on)
 * (starting with the one you just worked on) that needs something: water if dry, harvest if grown, clear if dead, plant if the lap is still
 * planting. A dry plant about to die jumps the queue.
 */
public final class Planner
{
	/** A dry plant with this many ticks or fewer left is urgent (12 seconds). */
	public static final int URGENT_TICKS = 20;
	/** Long enough to walk to the sack or barrel and back during a wait (18 seconds). */
	public static final int ERRAND_TICKS = 30;
	/** Staggered: plant a group while fewer than 2 other groups are in their first stage (keeps them spaced but busy). */
	static final int STAGGER_GROUPS = 2;

	private Planner()
	{
	}

	/**
	 * @param route  the style's patches in order
	 * @param cursor route index of the last patch the player worked on, or -1 at the start of a lap
	 */
	public static Instruction next(List<Plot> route, int cursor, Snapshot s, PlayStyle style, boolean outfitReminder)
	{
		if (!s.inFarm)
		{
			String seed = seedAdvice(s);
			return new Instruction(Action.ENTER, -1, "Enter the Tithe Farm",
				"Bring a seed dibber, a spade and " + style.cans() + " watering cans (or Gricoller's can)." + (seed.isEmpty() ? "" : " " + seed), Urgency.CALM);
		}
		int tick = s.tick;
		int n = route.size();

		int empty = 0;
		int growing = 0;
		int grown = 0;
		int dead = 0;
		int maxStage = 0;
		int wateringsLeft = 0;
		for (Plot p : route)
		{
			switch (p.getKind())
			{
				case EMPTY:
					empty++;
					break;
				case DEAD:
					dead++;
					break;
				case GROWN:
					grown++;
					break;
				default:
					growing++;
					maxStage = Math.max(maxStage, p.getStage());
					wateringsLeft += p.wateringsLeft();
					break;
			}
		}

		// 1. A dry plant is about to die: water it now.
		Plot urgent = null;
		for (Plot p : route)
		{
			if (p.getKind() == PlotKind.DRY)
			{
				int left = p.ticksLeft(tick);
				if (left >= 0 && left <= URGENT_TICKS && (urgent == null || left < urgent.ticksLeft(tick)))
				{
					urgent = p;
				}
			}
		}
		if (urgent != null)
		{
			if (s.water <= 0)
			{
				return new Instruction(Action.FILL_CANS, -1, "Out of water!",
					"Patch " + urgent.label() + " dies in " + secs(urgent.ticksLeft(tick)) + ". Fill a can at the barrel.", Urgency.NOW);
			}
			return new Instruction(Action.WATER, urgent.index, "Water patch " + urgent.label() + " now",
				"Dies in " + secs(urgent.ticksLeft(tick)), Urgency.NOW);
		}

		boolean lapActive = growing + grown + dead > 0;

		// 2. Between laps: deposit, refill, restock, then start planting.
		if (!lapActive)
		{
			if (s.fruit > 0)
			{
				return new Instruction(Action.DEPOSIT, -1, "Deposit " + s.fruit + " fruit in the sack",
					outfitReminder && s.outfitInInventory ? "Wear your farmer's outfit first (more deposit XP)" : "Then start the next lap", Urgency.CALM);
			}
			int need = 3 * n;
			if (s.water < need)
			{
				return new Instruction(Action.FILL_CANS, -1, "Fill your watering cans",
					"Water for " + s.water + "/" + need + " waterings. Use the barrel (or Humidify).", Urgency.CALM);
			}
			if (!s.canPlant || !s.hasSpade)
			{
				return new Instruction(Action.GET_TOOLS, -1, !s.canPlant ? "Get a seed dibber" : "Get a spade",
					"The Tool Leprechaun or the tool shelf in the farm has them.", Urgency.CALM);
			}
			if (s.seeds <= 0)
			{
				int best = Rewards.bestSeed(s.farmingLevel);
				if (best < 0 && s.farmingLevel >= 0)
				{
					return new Instruction(Action.GET_SEEDS, -1, "You need 34 Farming",
						"Tithe Farm seeds start at 34 Farming (you have " + s.farmingLevel + "). A boost works.", Urgency.SOON);
				}
				String title = best < 0 ? "Take seeds from the table" : "Take " + Rewards.SEED_NAMES[best] + " seeds";
				return new Instruction(Action.GET_SEEDS, -1, title, seedAdvice(s), Urgency.CALM);
			}
			if (style.usesFertiliser() && !s.hasFertiliser)
			{
				return new Instruction(Action.GET_TOOLS, -1, "Get Gricoller's fertiliser",
					"The Fertiliser style needs it for 2-minute laps.", Urgency.CALM);
			}
		}

		// Held seeds need the level when planting too: a boost that wore off stops you.
		boolean seedsTooHigh = s.seedTier >= 0 && s.farmingLevel >= 0 && s.farmingLevel < Rewards.SEED_LEVELS[s.seedTier];
		if (seedsTooHigh && empty > 0 && grown == 0 && maxStage <= 2)
		{
			return new Instruction(Action.GET_SEEDS, -1, "Boost wore off",
				Rewards.SEED_NAMES[s.seedTier] + " needs " + Rewards.SEED_LEVELS[s.seedTier] + " Farming to plant (you're "
					+ s.farmingLevel + "). Boost again or finish the lap.", Urgency.SOON);
		}

		// 3. Can we afford to plant one more (seeds, a dibber, water for its three waterings)?
		boolean canAfford = s.seeds > 0 && s.canPlant && !seedsTooHigh && s.water >= wateringsLeft + 3;
		// Laps: only while the lap is young and nothing has finished.
		boolean lapPlanting = empty > 0 && grown == 0 && maxStage <= 2 && canAfford;

		// 4. Outfit swap right before harvesting a lap (combo harvests constantly, so not there).
		if (!style.isContinuous() && outfitReminder && s.outfitInInventory && grown > 0 && growing == 0)
		{
			return new Instruction(Action.WEAR_OUTFIT, -1, "Put on your farmer's outfit",
				"More XP from harvesting and depositing", Urgency.CALM);
		}

		// 5. Next patch along the route that needs something, starting with the one you just
		// worked on (a patch you just planted still needs its water).
		int start = cursor < 0 ? 0 : cursor;
		for (int step = 0; step < n; step++)
		{
			int i = (start + step) % n;
			Plot p = route.get(i);
			switch (p.getKind())
			{
				case DRY:
					if (s.water <= 0)
					{
						return new Instruction(Action.FILL_CANS, -1, "Out of water",
							"Fill a can at the barrel. Patch " + p.label() + " dies in " + secs(p.ticksLeft(tick)), Urgency.SOON);
					}
					return new Instruction(Action.WATER, i, "Water patch " + p.label(),
						stageText(p, tick), p.ticksLeft(tick) <= 40 ? Urgency.SOON : Urgency.CALM);
				case WET:
					if (style.usesFertiliser() && s.hasFertiliser && p.getStage() == 1 && !p.isFertilised())
					{
						return new Instruction(Action.FERTILISE, i, "Fertilise patch " + p.label(),
							"Use Gricoller's fertiliser on it (it's watered). Grows twice as fast.", Urgency.CALM);
					}
					break;
				case GROWN:
					return new Instruction(Action.HARVEST, i, "Harvest patch " + p.label(),
						style.isContinuous() ? "Then replant and water it" : grown + " ready" + (growing > 0 ? ", " + growing + " still growing" : ""),
						Urgency.CALM);
				case DEAD:
					return new Instruction(Action.CLEAR, i, "Clear dead patch " + p.label(),
						"It missed a watering. Clear it (spade) so it can be replanted.", Urgency.CALM);
				case EMPTY:
					if (style.isContinuous() && s.seeds > 0 && s.canPlant && !seedsTooHigh && s.water < wateringsLeft + 3)
					{
						return new Instruction(Action.FILL_CANS, -1, "Refill your cans",
							"Not enough water to replant patch " + p.label() + " (need " + (wateringsLeft + 3) + ", have " + s.water + ")", Urgency.SOON);
					}
					if (mayPlant(route, i, style, lapPlanting, canAfford))
					{
						String how = style.usesFertiliser() ? "Plant it, water it, then fertilise it"
							: "Plant it, then water it straight away";
						String count = style.isContinuous() ? "" : " (" + (n - empty + 1) + "/" + n + ")";
						String upgrade = "";
						int best = Rewards.bestSeed(s.farmingLevel);
						if (s.seedTier >= 0 && best > s.seedTier)
						{
							upgrade = " · Take " + Rewards.SEED_NAMES[best] + " next visit";
						}
						return new Instruction(Action.PLANT, i, "Plant patch " + p.label(), how + count + upgrade, Urgency.CALM);
					}
					break;
				default:
					break;
			}
		}

		// 6. Nothing to do yet: say what's next and fit in an errand if there's time.
		Plot soonest = null;
		for (Plot p : route)
		{
			if (p.getKind() == PlotKind.WET && p.ticksLeft(tick) >= 0
				&& (soonest == null || p.ticksLeft(tick) < soonest.ticksLeft(tick)))
			{
				soonest = p;
			}
		}
		if (soonest == null)
		{
			if (empty > 0 && !lapActive)
			{
				return new Instruction(Action.WAIT, -1, "Ready", "Start planting at patch 1", Urgency.CALM);
			}
			return Instruction.NONE;
		}
		int wait = soonest.ticksLeft(tick);
		String next = soonest.getStage() >= 3 ? "Patch " + soonest.label() + " is grown in " + secs(wait)
			: "Water patch " + soonest.label() + " in " + secs(wait);
		if (wait >= ERRAND_TICKS && s.water < wateringsLeft)
		{
			return new Instruction(Action.FILL_CANS, -1, "Top up your cans", "Need " + wateringsLeft + ", have " + s.water + ". " + next, Urgency.SOON);
		}
		if (wait >= ERRAND_TICKS && style.isContinuous() && s.fruit >= 25)
		{
			return new Instruction(Action.DEPOSIT, -1, "Deposit " + s.fruit + " fruit", next, Urgency.CALM);
		}
		if (wait >= ERRAND_TICKS && style.isContinuous() && s.water < Math.max(wateringsLeft + 3 * PlayStyle.GROUP, n))
		{
			return new Instruction(Action.FILL_CANS, -1, "Top up your cans", next, Urgency.CALM);
		}
		if (wait >= ERRAND_TICKS && maxStage >= 3 && s.water < 3 * n && wateringsLeft == 0)
		{
			// Grown plants can't die, so the last wait is the best time to refill for next lap.
			return new Instruction(Action.FILL_CANS, -1, "Refill for next lap", next, Urgency.CALM);
		}
		return new Instruction(Action.WAIT, soonest.index, "Wait", next, Urgency.CALM);
	}

	/**
	 * Which seed to take at the table for your Farming level, e.g. "Farming 76: take Logavano (74+),
	 * 23 XP per fruit". Mentions a boost if the boosted level is what unlocks it.
	 */
	public static String seedAdvice(Snapshot s)
	{
		int best = Rewards.bestSeed(s.farmingLevel);
		if (best < 0)
		{
			return "";
		}
		String text = "Farming " + s.farmingLevel + ": take " + Rewards.SEED_NAMES[best] + " ("
			+ Rewards.SEED_LEVELS[best] + "+), " + (int) Rewards.XP_PER_FRUIT[best] + " XP per fruit.";
		int unboosted = Rewards.bestSeed(s.realFarmingLevel);
		if (s.realFarmingLevel >= 0 && unboosted < best)
		{
			text += " That's boosted: plant before it wears off.";
		}
		else if (best < Rewards.SEED_LEVELS.length - 1 && s.farmingLevel >= 0)
		{
			int next = Rewards.SEED_LEVELS[best + 1];
			if (next - s.farmingLevel <= 5)
			{
				text += " A +" + (next - s.farmingLevel) + " boost unlocks " + Rewards.SEED_NAMES[best + 1] + ".";
			}
		}
		return text;
	}

	private static String stageText(Plot p, int tick)
	{
		int left = p.ticksLeft(tick);
		return "Stage " + p.getStage() + "/3" + (left >= 0 ? " · " + secs(left) + " left" : "");
	}

	/**
	 * Laps plant only while the lap is young. Combo replants any empty patch it passes. Staggered
	 * plants a group of 4 only when no other group is still in its first stage, which spaces the
	 * groups a stage apart (the wiki's setup: plant A, then water A and plant B, and so on).
	 */
	static boolean mayPlant(List<Plot> route, int index, PlayStyle style, boolean lapPlanting, boolean canAfford)
	{
		switch (style.mode())
		{
			case COMBO:
				return canAfford;
			case STAGGERED:
				if (!canAfford)
				{
					return false;
				}
				int group = index / PlayStyle.GROUP;
				java.util.Set<Integer> young = new java.util.HashSet<>();
				for (Plot p : route)
				{
					if (p.index / PlayStyle.GROUP != group && p.isGrowing() && p.getStage() == 1)
					{
						young.add(p.index / PlayStyle.GROUP);
					}
				}
				return young.size() < STAGGER_GROUPS;
			default:
				return lapPlanting;
		}
	}

	/** Ticks as seconds, "0:36". */
	public static String secs(int ticks)
	{
		int s = (int) Math.round(Math.max(0, ticks) * 0.6);
		return s / 60 + ":" + (s % 60 < 10 ? "0" : "") + s % 60;
	}
}

package com.toadfx.tithefarmautopilot.logic;

/**
 * Every method: which patches, in what order, and how the lap works. Routes and rates are from the
 * OSRS Wiki's Tithe Farm strategies page.
 */
public enum PlayStyle
{
	CHILL("Chill", "Low effort: 8-12 plants on the basic route with plenty of slack", Route.BASIC_20, Mode.LAPS, false, 4),
	STEADY("Steady", "Moderate: the wiki's basic 20 (or 16). Plant + water, water, water, harvest", Route.BASIC_20, Mode.LAPS, false, 8),
	FERTILISER("Fertiliser", "10 plants: water each one, then use Gricoller's fertiliser on it. Laps take under 2 minutes", Route.BASIC_20, Mode.LAPS, true, 4),
	COMBO_20("Combo 20", "Harvest, replant and water each patch in one visit, round and round. ~107 points/hr, ~108k XP/hr (Logavano)", Route.COMBO_20, Mode.COMBO, false, 8),
	SIMPLE_23("23x", "23 plants, no tick tricks or precise clicking. Bring 9 cans", Route.SIMPLE_23, Mode.LAPS, false, 9),
	R24X("24x", "The 25x4 route without the lone patch: practice for 25x4. Bring 10 cans", Route.R24X, Mode.LAPS, false, 10),
	R25_EASY("25x easy", "25 plants, no manual watering or tile markers. Plants 18, 19, 22 and 23 from the side. Bring 10+ cans", Route.R25_EASY, Mode.LAPS, false, 10),
	R25X4("25x4", "Max XP / points: four rounds of 25. ~115k XP/hr and ~110 points/hr with Logavano. Bring 10 cans", Route.R25X4, Mode.LAPS, false, 10),
	R25_RECURSIVE("25x recursive", "25 plants in an order that repeats every lap with no correction clicks. Bring 10 cans", Route.R25_RECURSIVE, Mode.LAPS, false, 10),
	R24_COMBO("24x combo", "Combo on the centre three columns: harvest, replant and water in one visit. Needs near-perfect play", Route.R24_COMBO, Mode.COMBO, false, 10),
	STAGGERED("Staggered", "Experimental: 24 patches in 6 groups of 4, each group a stage apart. Steady and continuous, but no breaks", Route.R24X, Mode.STAGGERED, false, 10);

	/** How a lap works. */
	public enum Mode
	{
		/** Plant everything, water it twice more, harvest everything, deposit and refill. */
		LAPS,
		/** One visit per patch: harvest, replant and water, then on to the next. Never-ending. */
		COMBO,
		/** Like combo, but groups of 4 are planted a stage apart so there's always something to do. */
		STAGGERED
	}

	public static final int GROUP = 4;

	private final String shortName;
	private final String description;
	private final int[] route;
	private final Mode mode;
	private final boolean fertiliser;
	private final int cans;

	PlayStyle(String shortName, String description, int[] route, Mode mode, boolean fertiliser, int cans)
	{
		this.shortName = shortName;
		this.description = description;
		this.route = route;
		this.mode = mode;
		this.fertiliser = fertiliser;
		this.cans = cans;
	}

	public String shortName()
	{
		return shortName;
	}

	public String description()
	{
		return description;
	}

	public int[] route()
	{
		return route;
	}

	public Mode mode()
	{
		return mode;
	}

	public boolean isContinuous()
	{
		return mode != Mode.LAPS;
	}

	public boolean usesFertiliser()
	{
		return fertiliser;
	}

	/** Watering cans to bring (or a Gricoller's can). */
	public int cans()
	{
		return cans;
	}

	/** Plants per lap for this style given the player's settings. */
	public int plants(int chillPlants, boolean steadyCutoff16)
	{
		switch (this)
		{
			case CHILL:
				return Math.max(8, Math.min(12, chillPlants));
			case STEADY:
				return steadyCutoff16 ? 16 : 20;
			case FERTILISER:
				return 10;
			default:
				return route.length / 2;
		}
	}

	@Override
	public String toString()
	{
		return shortName;
	}
}

package com.toadfx.tithefarmautopilot.logic;

/** One patch on the route, with the tick its current growth stage started. */
public final class Plot
{
	/** Stage length with no fertiliser: one minute. */
	public static final int NORMAL_STAGE_TICKS = 100;
	/** Gricoller's fertiliser doubles growth speed. */
	public static final int FAST_STAGE_TICKS = 50;

	/** Position on the route, from 0. Shown to the player as index + 1. */
	public final int index;
	/** Tile inside map region 7222 (the plot's centre). */
	public final int regionX;
	public final int regionY;

	private PlotKind kind = PlotKind.EMPTY;
	private int stage;
	private int stageStart = -1;
	private int stageTicks = NORMAL_STAGE_TICKS;
	private boolean seen;
	private boolean fertilised;

	public Plot(int index, int regionX, int regionY)
	{
		this.index = index;
		this.regionX = regionX;
		this.regionY = regionY;
	}

	/**
	 * Records the patch's new look. Returns what changed so the caller can tell who did it
	 * (planting, watering and harvesting are the player; a stage change is the game).
	 */
	public Change update(PlotKind newKind, int newStage, int tick)
	{
		PlotKind oldKind = kind;
		int oldStage = stage;
		boolean wasSeen = seen;
		seen = true;
		kind = newKind;
		stage = newStage;

		if (!wasSeen)
		{
			stageStart = tick;
			return Change.FIRST_SEEN;
		}
		if (oldKind == newKind && oldStage == newStage)
		{
			return Change.NONE;
		}
		if (oldKind == PlotKind.EMPTY && (newKind == PlotKind.DRY || newKind == PlotKind.WET))
		{
			stageStart = tick;
			fertilised = false;
			stageTicks = NORMAL_STAGE_TICKS;
			return Change.PLANTED;
		}
		if (newKind == PlotKind.EMPTY)
		{
			stageStart = -1;
			fertilised = false;
			stageTicks = NORMAL_STAGE_TICKS;
			return oldKind == PlotKind.GROWN ? Change.HARVESTED : Change.CLEARED;
		}
		if (newKind == PlotKind.DEAD)
		{
			stageStart = tick;
			return Change.DIED;
		}
		if (oldStage == newStage && oldKind == PlotKind.DRY && newKind == PlotKind.WET)
		{
			return Change.WATERED;
		}
		// A new stage (or grown). Learn the stage length so fertilised plants time correctly.
		if (newStage == oldStage + 1 && stageStart >= 0)
		{
			int took = tick - stageStart;
			if (took > 20 && took < 140)
			{
				stageTicks = took < 75 ? FAST_STAGE_TICKS : NORMAL_STAGE_TICKS;
				fertilised = fertilised || stageTicks == FAST_STAGE_TICKS;
			}
		}
		stageStart = tick;
		return newKind == PlotKind.GROWN ? Change.GREW : Change.NEW_STAGE;
	}

	/** Gricoller's fertiliser was used on it: it grows twice as fast from now on. */
	public void markFertilised(int tick)
	{
		if (!isGrowing() || fertilised)
		{
			return;
		}
		fertilised = true;
		if (stageStart >= 0)
		{
			// Whatever is left of this stage now goes twice as fast.
			int left = Math.max(0, stageStart + stageTicks - tick);
			stageTicks = FAST_STAGE_TICKS;
			stageStart = tick + left / 2 - FAST_STAGE_TICKS;
		}
		else
		{
			stageTicks = FAST_STAGE_TICKS;
		}
	}

	public boolean isFertilised()
	{
		return fertilised;
	}

	public void forget()
	{
		kind = PlotKind.EMPTY;
		stage = 0;
		stageStart = -1;
		seen = false;
		fertilised = false;
		stageTicks = NORMAL_STAGE_TICKS;
	}

	public PlotKind getKind()
	{
		return kind;
	}

	public int getStage()
	{
		return stage;
	}

	public boolean isSeen()
	{
		return seen;
	}

	public boolean isGrowing()
	{
		return (kind == PlotKind.DRY || kind == PlotKind.WET) && stage >= 1 && stage <= 3;
	}

	public int getStageTicks()
	{
		return stageTicks;
	}

	public void setStageTicks(int ticks)
	{
		stageTicks = ticks;
	}

	/** Ticks until this stage ends (a dry plant dies then), or -1 if not growing. */
	public int ticksLeft(int tick)
	{
		if (!isGrowing() || stageStart < 0)
		{
			return -1;
		}
		return Math.max(0, stageStart + stageTicks - tick);
	}

	/** 0..1 through the current stage, for the timer pie. */
	public double stageProgress(int tick)
	{
		if (!isGrowing() || stageStart < 0)
		{
			return 0;
		}
		return Math.min(1.0, Math.max(0, (tick - stageStart) / (double) stageTicks));
	}

	/** Waterings this plant still needs before it's grown. */
	public int wateringsLeft()
	{
		if (kind == PlotKind.DRY)
		{
			return 4 - stage;
		}
		if (kind == PlotKind.WET)
		{
			return 3 - stage;
		}
		return 0;
	}

	public String label()
	{
		return String.valueOf(index + 1);
	}

	public enum Change
	{
		NONE, FIRST_SEEN, PLANTED, WATERED, NEW_STAGE, GREW, HARVESTED, DIED, CLEARED
	}
}

package com.toadfx.tithefarmautopilot.logic;

/**
 * Turns a Tithe Farm patch object ID into its state.
 *
 * <p>The game numbers the patches in one run: the empty patch (HOSIDIUS_TITHE_EMPTY, 27383), then
 * eleven IDs per seed (Golovanova, Bologano, Logavano): stages 1-3 as dry, wet and dead, then grown
 * and grown-dead. So HOSIDIUS_TITHE_A_1_DRY is 27384 and HOSIDIUS_TITHE_C_4_DEAD is 27416. The
 * numbers are checked against RuneLite's gameval ObjectID in IdsTest.
 */
public final class PlotIds
{
	public static final int EMPTY = 27383;
	public static final int FIRST = 27384;
	public static final int LAST = 27416;
	public static final int PER_SEED = 11;

	private PlotIds()
	{
	}

	public static boolean isPlot(int id)
	{
		return id >= EMPTY && id <= LAST;
	}

	/** Returns the state, or null if this isn't a Tithe Farm patch. */
	public static Decoded decode(int id)
	{
		if (id == EMPTY)
		{
			return new Decoded(PlotKind.EMPTY, 0, -1);
		}
		if (id < FIRST || id > LAST)
		{
			return null;
		}
		int offset = id - FIRST;
		int seed = offset / PER_SEED;
		int within = offset % PER_SEED;
		if (within == 9)
		{
			return new Decoded(PlotKind.GROWN, 4, seed);
		}
		if (within == 10)
		{
			return new Decoded(PlotKind.DEAD, 4, seed);
		}
		int stage = within / 3 + 1;
		switch (within % 3)
		{
			case 0:
				return new Decoded(PlotKind.DRY, stage, seed);
			case 1:
				return new Decoded(PlotKind.WET, stage, seed);
			default:
				return new Decoded(PlotKind.DEAD, stage, seed);
		}
	}

	public static final class Decoded
	{
		public final PlotKind kind;
		/** 1-3 while growing, 4 when grown, 0 when empty. */
		public final int stage;
		/** 0 Golovanova, 1 Bologano, 2 Logavano, -1 none. */
		public final int seed;

		Decoded(PlotKind kind, int stage, int seed)
		{
			this.kind = kind;
			this.stage = stage;
			this.seed = seed;
		}
	}
}

