package com.toadfx.tithefarmautopilot.logic;

import java.util.ArrayList;
import java.util.Collection;
import java.util.EnumSet;
import java.util.List;
import java.util.Set;

/**
 * Plans the shop: walks your rewards in order, skipping what you own, and works out the running
 * total of points, what you can buy now, and the fruit, laps and time left for the rest.
 */
public final class RewardPlan
{
	/** ToadFx's suggested order: the can first (fewer refills makes every lap after it faster). */
	public static final List<Reward> DEFAULT_ORDER = List.of(
		Reward.GRICOLLERS_CAN, Reward.FARMERS_JACKET, Reward.FARMERS_TROUSERS, Reward.FARMERS_HAT,
		Reward.FARMERS_BOOTS, Reward.SEED_BOX, Reward.HERB_SACK, Reward.AUTO_WEED);

	public enum Status
	{
		OWNED, BUY_NOW, SAVING, LOCKED
	}

	public static final class Row
	{
		public final Reward reward;
		public final Status status;
		/** Points needed to buy this and everything before it (not owned, not locked). */
		public final int cumulative;
		public final int pointsLeft;
		public final int fruitLeft;
		public final int lapsLeft;
		/** Minutes at the current rate, or -1 if unknown. */
		public final int minutesLeft;

		Row(Reward reward, Status status, int cumulative, int pointsLeft, int fruitLeft, int lapsLeft, int minutesLeft)
		{
			this.reward = reward;
			this.status = status;
			this.cumulative = cumulative;
			this.pointsLeft = pointsLeft;
			this.fruitLeft = fruitLeft;
			this.lapsLeft = lapsLeft;
			this.minutesLeft = minutesLeft;
		}
	}

	private RewardPlan()
	{
	}

	/**
	 * @param order         rewards in the order you want them
	 * @param owned         rewards you already have
	 * @param points        Tithe points now
	 * @param herblore      real Herblore level (-1 if unknown, treated as enough)
	 * @param plants        plants per lap (for laps left)
	 * @param pointsPerHour your rate, or 0 if unknown
	 */
	public static List<Row> plan(List<Reward> order, Set<Reward> owned, int points, int herblore, int plants, double pointsPerHour)
	{
		List<Row> rows = new ArrayList<>();
		int cumulative = 0;
		int have = Math.max(0, points);
		for (Reward r : order)
		{
			if (owned.contains(r))
			{
				rows.add(new Row(r, Status.OWNED, cumulative, 0, 0, 0, 0));
				continue;
			}
			if (herblore >= 0 && herblore < r.herbloreNeeded())
			{
				rows.add(new Row(r, Status.LOCKED, cumulative, 0, 0, 0, -1));
				continue;
			}
			cumulative += r.cost();
			int left = Math.max(0, cumulative - have);
			if (left == 0)
			{
				rows.add(new Row(r, Status.BUY_NOW, cumulative, 0, 0, 0, 0));
			}
			else
			{
				int minutes = pointsPerHour > 0 ? (int) Math.ceil(left / pointsPerHour * 60) : -1;
				rows.add(new Row(r, Status.SAVING, cumulative, left, Rewards.fruitFor(left), Rewards.lapsFor(left, plants), minutes));
			}
		}
		return rows;
	}

	/** The first reward you don't own and can buy (by level), or null when the plan is done. */
	public static Row next(List<Row> rows)
	{
		for (Row r : rows)
		{
			if (r.status == Status.BUY_NOW || r.status == Status.SAVING)
			{
				return r;
			}
		}
		return null;
	}

	/** Points left for everything you still want, or 0. */
	public static int pointsLeftForAll(List<Row> rows)
	{
		int max = 0;
		for (Row r : rows)
		{
			max = Math.max(max, r.pointsLeft);
		}
		return max;
	}

	/** Points per hour from plants per lap and lap time: 35 points per 100 fruit. */
	public static double estimatePointsPerHour(int plants, int lapSeconds)
	{
		if (plants <= 0 || lapSeconds <= 0)
		{
			return 0;
		}
		return plants * 0.35 * 3600.0 / lapSeconds;
	}

	// ---------------------------------------------------------------- saving in the config

	public static String encodeOrder(List<Reward> order)
	{
		StringBuilder sb = new StringBuilder();
		for (Reward r : order)
		{
			if (sb.length() > 0)
			{
				sb.append(',');
			}
			sb.append(r.name());
		}
		return sb.toString();
	}

	/** Reads a saved order; unknown names are dropped and missing rewards go on the end. */
	public static List<Reward> decodeOrder(String s)
	{
		List<Reward> order = new ArrayList<>();
		if (s != null)
		{
			for (String part : s.split(","))
			{
				try
				{
					Reward r = Reward.valueOf(part.trim());
					if (!order.contains(r))
					{
						order.add(r);
					}
				}
				catch (IllegalArgumentException ignored)
				{
					// Renamed or removed reward.
				}
			}
		}
		for (Reward r : DEFAULT_ORDER)
		{
			if (!order.contains(r))
			{
				order.add(r);
			}
		}
		return order;
	}

	public static String encodeOwned(Collection<Reward> owned)
	{
		return encodeOrder(new ArrayList<>(owned));
	}

	public static Set<Reward> decodeOwned(String s)
	{
		Set<Reward> owned = EnumSet.noneOf(Reward.class);
		if (s != null && !s.isEmpty())
		{
			for (String part : s.split(","))
			{
				try
				{
					owned.add(Reward.valueOf(part.trim()));
				}
				catch (IllegalArgumentException ignored)
				{
					// Renamed or removed reward.
				}
			}
		}
		return owned;
	}

	/** Moves a reward one place earlier. */
	public static List<Reward> moveUp(List<Reward> order, Reward r)
	{
		List<Reward> copy = new ArrayList<>(order);
		int i = copy.indexOf(r);
		if (i > 0)
		{
			copy.remove(i);
			copy.add(i - 1, r);
		}
		return copy;
	}
}

package com.toadfx.tithefarmautopilot.logic;

/**
 * Points, XP and shop maths from the OSRS Wiki.
 *
 * <p>1 point per 3 fruit deposited, plus 2 bonus points per 100 (35 for a full 100). Points cap at
 * 16,000. Harvest XP per fruit is 6 / 14 / 23 (Golovanova / Bologano / Logavano). Depositing gives
 * ten times that per fruit, doubled for fruit 75-100 of a run, and the 75th fruit adds a bonus of
 * 250x the harvest rate. A full 100 is 9,660 / 22,540 / 37,030 XP.
 */
public final class Rewards
{
	public static final int POINT_CAP = 16000;
	public static final String[] SEED_NAMES = {"Golovanova", "Bologano", "Logavano"};
	public static final int[] SEED_LEVELS = {34, 54, 74};
	public static final double[] XP_PER_FRUIT = {6, 14, 23};

	private Rewards()
	{
	}

	/** Points for depositing this many fruit in one session. */
	public static int points(int fruit)
	{
		if (fruit <= 0)
		{
			return 0;
		}
		return fruit / 3 + 2 * (fruit / 100);
	}

	/** Fruit needed to earn this many points (35 per 100). */
	public static int fruitFor(int points)
	{
		if (points <= 0)
		{
			return 0;
		}
		int fruit = (int) Math.ceil(points * 100 / 35.0);
		while (points(fruit) < points)
		{
			fruit++;
		}
		while (fruit > 0 && points(fruit - 1) >= points)
		{
			fruit--;
		}
		return fruit;
	}

	/** Laps of {@code plants} fruit to earn {@code points}. */
	public static int lapsFor(int points, int plants)
	{
		if (points <= 0 || plants <= 0)
		{
			return 0;
		}
		return (int) Math.ceil(fruitFor(points) / (double) plants);
	}

	/** Best seed for a Farming level: 0, 1, 2, or -1 below 34. */
	public static int bestSeed(int farmingLevel)
	{
		for (int i = SEED_LEVELS.length - 1; i >= 0; i--)
		{
			if (farmingLevel >= SEED_LEVELS[i])
			{
				return i;
			}
		}
		return -1;
	}

	/** Harvest + deposit XP for a 100-fruit run (no outfit), e.g. 37,030 for Logavano. */
	public static double fullSackXp(int seed)
	{
		double per = XP_PER_FRUIT[seed];
		return 100 * per + 74 * per * 10 + 26 * per * 20 + 250 * per;
	}

	/** Fruit left until the 75th-fruit bonus, or 0 once it's passed this run. */
	public static int toBonus(int depositedThisRun)
	{
		int inRun = depositedThisRun % 100;
		return inRun < 75 ? 75 - inRun : 0;
	}
}

package com.toadfx.tithefarmautopilot.logic;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * Patch orders for every method, from the OSRS Wiki's Tithe Farm strategy tile markers.
 *
 * <p>The farm (map region 7222) has five patch columns centred at region x 19, 24, 29, 34 and 39.
 * Each column has four patches in the south half (y 33, 36, 39, 42) and four in the north half
 * (48, 51, 54, 57), plus one lone patch at (29, 27). Each patch is 3x3 tiles. Coordinates here are
 * patch centres. Where the wiki marks the tile you stand on, it's been mapped to the patch beside
 * it (the 3x3 patch nearest that tile).
 */
public final class Route
{
	public static final int REGION = 7222;

	/** Basic 20: zig-zag the two east columns (north half), down the far east and back up its
	 * neighbour (south half), then up the middle column's north half. Can be cut off at 16. */
	public static final int[] BASIC_20 = {
		34, 57, 39, 57, 34, 54, 39, 54, 39, 51, 34, 51, 34, 48, 39, 48,
		39, 42, 39, 39, 39, 36, 39, 33, 34, 33, 34, 36, 34, 39, 34, 42,
		29, 48, 29, 51, 29, 54, 29, 57,
	};

	/** Combo 20: zig-zag both west columns top to bottom, then up the middle column's south half. */
	public static final int[] COMBO_20 = {
		19, 57, 24, 57, 24, 54, 19, 54, 19, 51, 24, 51, 24, 48, 19, 48,
		19, 42, 24, 42, 24, 39, 19, 39, 19, 36, 24, 36, 24, 33, 19, 33,
		29, 33, 29, 36, 29, 39, 29, 42,
	};

	/** 23x: down the middle column to the lone patch, then back up the west side. */
	public static final int[] SIMPLE_23 = {
		24, 57, 29, 57, 24, 54, 29, 54, 24, 51, 29, 51, 29, 48, 29, 42,
		29, 39, 29, 36, 29, 33, 29, 27, 19, 33, 19, 36, 24, 39, 19, 39,
		24, 42, 19, 42, 24, 48, 19, 48, 19, 51, 19, 54, 19, 57,
	};

	/** 25x4: the centre three columns plus the lone patch, four rounds of 25. */
	public static final int[] R25X4 = {
		29, 42, 24, 42, 24, 39, 24, 36, 29, 36, 24, 33, 29, 27, 34, 33,
		29, 33, 34, 36, 34, 39, 29, 39, 34, 42, 34, 48, 34, 51, 29, 51,
		34, 54, 34, 57, 29, 57, 24, 57, 24, 54, 29, 54, 24, 51, 24, 48,
		29, 48,
	};

	/** 25x easy: east-centre column first, plants 18, 19, 22 and 23 are tended from the side. */
	public static final int[] R25_EASY = {
		34, 33, 34, 36, 34, 39, 34, 42, 34, 48, 29, 48, 29, 51, 34, 51,
		34, 54, 29, 54, 29, 57, 34, 57, 24, 57, 24, 54, 24, 51, 24, 48,
		24, 42, 29, 42, 29, 39, 24, 39, 24, 36, 29, 36, 29, 33, 24, 33,
		29, 27,
	};

	/** 25x recursive: the same 25 patches in an order that repeats every lap without corrections. */
	public static final int[] R25_RECURSIVE = {
		34, 33, 34, 36, 34, 39, 34, 42, 29, 48, 34, 48, 34, 51, 29, 51,
		29, 54, 34, 54, 34, 57, 29, 57, 24, 57, 24, 54, 24, 51, 24, 48,
		29, 42, 24, 42, 24, 39, 29, 39, 29, 36, 24, 36, 24, 33, 29, 33,
		29, 27,
	};

	/** 24x combo: harvest, replant and water in one visit around the centre three columns. */
	public static final int[] R24_COMBO = {
		29, 57, 34, 57, 34, 54, 29, 51, 34, 51, 34, 48, 34, 42, 29, 39,
		34, 39, 34, 36, 34, 33, 29, 33, 29, 27, 24, 33, 24, 36, 29, 36,
		24, 39, 24, 42, 29, 42, 24, 48, 24, 51, 24, 54, 29, 54, 24, 57,
	};

	/** 24x: the 25x4 route without the lone patch. */
	public static final int[] R24X = without(R25X4, 29, 27);

	public static final int MAX = 25;

	private Route()
	{
	}

	/** The first {@code plants} patches of a route, numbered from 0. */
	public static List<Plot> build(int[] route, int plants)
	{
		int n = Math.max(1, Math.min(route.length / 2, plants));
		List<Plot> list = new ArrayList<>(n);
		for (int i = 0; i < n; i++)
		{
			list.add(new Plot(i, route[i * 2], route[i * 2 + 1]));
		}
		return Collections.unmodifiableList(list);
	}

	/** Route position of the patch centred on this region tile, or -1 if it's not on the route. */
	public static int indexOf(int[] route, int regionX, int regionY, int plants)
	{
		int n = Math.min(route.length / 2, plants);
		for (int i = 0; i < n; i++)
		{
			if (route[i * 2] == regionX && route[i * 2 + 1] == regionY)
			{
				return i;
			}
		}
		return -1;
	}

	/** True if this region tile is the centre of a real Tithe Farm patch. */
	public static boolean isPatch(int x, int y)
	{
		if (x == 29 && y == 27)
		{
			return true;
		}
		boolean col = x == 19 || x == 24 || x == 29 || x == 34 || x == 39;
		boolean row = y == 33 || y == 36 || y == 39 || y == 42 || y == 48 || y == 51 || y == 54 || y == 57;
		return col && row;
	}

	private static int[] without(int[] route, int x, int y)
	{
		int[] out = new int[route.length - 2];
		int j = 0;
		for (int i = 0; i < route.length; i += 2)
		{
			if (route[i] == x && route[i + 1] == y)
			{
				continue;
			}
			out[j++] = route[i];
			out[j++] = route[i + 1];
		}
		return out;
	}
}

package com.toadfx.tithefarmautopilot.logic;

/** What the planner needs to know about the player each tick. Plain fields so tests can fill it in. */
public final class Snapshot
{
	public boolean inFarm;
	public int tick;
	public int seeds;
	/** Water left: doses in normal cans plus Gricoller's can charges. */
	public int water;
	/** Doses in normal watering cans only (the plugin adds Gricoller's can charges). */
	public int cansWater;
	public boolean hasGricollerCan;
	public int cans;
	public boolean canPlant = true;
