import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/** Pulses the screen red while a dry plant is about to die. */
public class DangerFlashOverlay extends Overlay
{
	private static final double PULSE_MS = 900.0;

	private final Client client;
	private final TitheFarmAutopilotPlugin plugin;
	private final TitheFarmAutopilotConfig config;

	@Inject
	public DangerFlashOverlay(Client client, TitheFarmAutopilotPlugin plugin, TitheFarmAutopilotConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
		setPriority(PRIORITY_LOW);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!config.dangerFlash() || !plugin.isInFarm() || plugin.getInstruction().getUrgency() != Urgency.NOW)
		{
			return null;
		}
		Color c = config.flashColor();
		double phase = (System.currentTimeMillis() % (long) PULSE_MS) / PULSE_MS;
		double strength = 0.6 + 0.4 * (0.5 + 0.5 * Math.cos(phase * 2 * Math.PI));
		int alpha = (int) Math.round(c.getAlpha() * strength);
		g.setColor(new Color(c.getRed(), c.getGreen(), c.getBlue(), Math.max(0, Math.min(255, alpha))));
		g.fillRect(0, 0, client.getCanvasWidth(), client.getCanvasHeight());
		return null;
	}
}

