/** Outlines the item the step needs: fertiliser, seeds or a watering can. */
public class InventoryOverlay extends WidgetItemOverlay
{
	private final TitheFarmAutopilotPlugin plugin;
	private final TitheFarmAutopilotConfig config;
	private final ItemManager itemManager;

	@Inject
	public InventoryOverlay(TitheFarmAutopilotPlugin plugin, TitheFarmAutopilotConfig config, ItemManager itemManager)
	{
		this.plugin = plugin;
		this.config = config;
		this.itemManager = itemManager;
		showOnInventory();
	}

	@Override
	public void renderItemOverlay(Graphics2D g, int itemId, WidgetItem item)
	{
