import net.runelite.client.ui.overlay.components.ProgressPieComponent;

/** Draws on the patches: route numbers, state colours, timers and the next patch. */
public class SceneOverlay extends Overlay
{
	private final Client client;
	private final TitheFarmAutopilotPlugin plugin;
	private final TitheFarmAutopilotConfig config;

	@Inject
	public SceneOverlay(Client client, TitheFarmAutopilotPlugin plugin, TitheFarmAutopilotConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!plugin.isInFarm())
		{
			return null;
		}
		List<Plot> route = plugin.getFarm().getRoute();
		Instruction step = plugin.getInstruction();
		int tick = client.getTickCount();
		g.setFont(FontManager.getRunescapeBoldFont());

		// The seed table, sack or barrel when the step is an errand.
		GameObject errand = plugin.getErrandObject();
		if (errand != null && config.highlightTarget())
		{
			Shape hull = errand.getConvexHull();
			if (hull != null)
			{
				Color t = config.targetColor();
				g.setColor(new Color(t.getRed(), t.getGreen(), t.getBlue(), 50));
				g.fill(hull);
				g.setColor(t);
				g.setStroke(new BasicStroke(2.5f));
				g.draw(hull);
			}
		}

		for (Plot p : route)
		{
			GameObject obj = plugin.objectFor(p.index);
			if (obj == null)
			{
				continue;
			}
			LocalPoint lp = obj.getLocalLocation();
			boolean isTarget = step.getTarget() == p.index && step.getAction() != Action.WAIT;
			Color c = colourFor(p, tick);

			Polygon tile = Perspective.getCanvasTileAreaPoly(client, lp, 3);
			if (tile != null)
			{
				if (isTarget && config.highlightTarget())
				{
					Color t = config.targetColor();
					g.setColor(new Color(t.getRed(), t.getGreen(), t.getBlue(), 50));
					g.fill(tile);
					g.setColor(t);
					g.setStroke(new BasicStroke(3f));
					g.draw(tile);
				}
				else if (config.outlineRoute() && c != null)
				{
					g.setColor(c);
					g.setStroke(new BasicStroke(1.5f));
					g.draw(tile);
				}
			}

			if (config.showTimers() && p.isGrowing())
			{
				Point centre = Perspective.localToCanvas(client, lp, client.getTopLevelWorldView().getPlane(), 150);
				if (centre != null)
				{
					ProgressPieComponent pie = new ProgressPieComponent();
					pie.setPosition(centre);
					pie.setProgress(1 - p.stageProgress(tick));
					Color fill = c == null ? Color.WHITE : c;
					pie.setFill(new Color(fill.getRed(), fill.getGreen(), fill.getBlue(), 140));
					pie.setBorderColor(fill);
					pie.setDiameter(18);
					pie.render(g);
				}
			}

			if (config.showNumbers())
			{
				String text = p.label();
				if (isTarget && config.highlightTarget())
				{
					text = verb(step.getAction()) + " " + text;
				}
				Point pt = Perspective.getCanvasTextLocation(client, g, lp, text, 40);
				if (pt != null)
				{
					OverlayUtil.renderTextLocation(g, pt, text, isTarget ? config.targetColor() : (c == null ? Color.WHITE : c));
				}
			}
		}
		return null;
	}

	private Color colourFor(Plot p, int tick)
	{
		switch (p.getKind())
		{
			case EMPTY:
				return p.isSeen() ? config.plantColor() : null;
			case DRY:
				int left = p.ticksLeft(tick);
				return left >= 0 && left <= Planner.URGENT_TICKS ? config.dangerColor() : config.waterColor();
			case WET:
				return config.wetColor();
			case GROWN:
				return config.harvestColor();
			case DEAD:
				return config.dangerColor();
			default:
				return null;
		}
	}

	private static String verb(Action a)
	{
		switch (a)
		{
			case PLANT:
				return "Plant";
			case WATER:
				return "Water";
			case HARVEST:
				return "Harvest";
			case CLEAR:
				return "Clear";
			default:
				return "";
		}
	}
}

