import net.runelite.client.ui.overlay.components.TitleComponent;
import net.runelite.client.util.QuantityFormatter;

/** Sack, points, goal and rates. */
public class SessionOverlay extends OverlayPanel
{
	private final TitheFarmAutopilotPlugin plugin;
	private final TitheFarmAutopilotConfig config;

	@Inject
	public SessionOverlay(TitheFarmAutopilotPlugin plugin, TitheFarmAutopilotConfig config)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!config.showSession() || !plugin.isNearFarm())
		{
			return null;
		}
		Session s = plugin.getSession();
		long now = System.currentTimeMillis();
		int score = plugin.getScore();
		int points = plugin.getPoints();
		panelComponent.setPreferredSize(new Dimension(170, 0));
		panelComponent.getChildren().add(TitleComponent.builder().text("Tithe Farm Autopilot").color(config.targetColor()).build());
		if (score >= 0)
		{
			int toBonus = Rewards.toBonus(score);
			line("Sack", (score % 100) + "/100", Color.WHITE);
			if (toBonus > 0 && toBonus <= 25)
			{
				line("75th bonus in", String.valueOf(toBonus), config.waterColor());
			}
		}
		if (points >= 0)
		{
			line("Points", QuantityFormatter.formatNumber(points), Color.WHITE);
		}
		int target = plugin.getGoalTarget();
		if (target > 0 && points >= 0)
		{
			int left = target - points;
			line("Next", plugin.getGoalName(), Color.WHITE);
			if (left <= 0)
			{
				line("Points", "buy it now!", config.harvestColor());
			}
			else
			{
				line("Points left", String.valueOf(left), Color.WHITE);
				line("Laps left", "~" + Rewards.lapsFor(left, plugin.getFarm().size()), Color.LIGHT_GRAY);
			}
		}
		if (s.isStarted())
		{
			line("Laps", s.getLaps() + (s.getDeaths() > 0 ? " (" + s.getDeaths() + " dead)" : ""), Color.LIGHT_GRAY);
			int xpHr = s.perHour(s.getXp(), now);
			if (xpHr > 0)
			{
				line("XP/hr", QuantityFormatter.quantityToStackSize(xpHr), Color.LIGHT_GRAY);
			}
			int ptsHr = s.perHour(s.getPoints(), now);
			if (ptsHr > 0)
			{
				line("Points/hr", String.valueOf(ptsHr), Color.LIGHT_GRAY);
			}
		}
		return super.render(g);
	}

	private void line(String left, String right, Color c)
	{
		panelComponent.getChildren().add(LineComponent.builder().left(left).right(right).rightColor(c).build());
	}
}

