/** The next-step box. */
public class StepOverlay extends OverlayPanel
{
	private static final Color MUTED = new Color(200, 200, 200);

	private final Client client;
	private final TitheFarmAutopilotPlugin plugin;
	private final TitheFarmAutopilotConfig config;

	@Inject
	public StepOverlay(Client client, TitheFarmAutopilotPlugin plugin, TitheFarmAutopilotConfig config)
	{
		super(plugin);
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_CENTER);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		Instruction step = plugin.getInstruction();
		if (!config.showStep() || !plugin.isNearFarm() || step.isEmpty())
		{
			return null;
		}
		Farm farm = plugin.getFarm();
		panelComponent.setPreferredSize(new Dimension(250, 0));
		panelComponent.getChildren().add(TitleComponent.builder()
			.text("TITHE · " + config.playStyle().shortName().toUpperCase() + " " + farm.size())
			.color(config.targetColor())
			.build());
		Color color = step.getUrgency() == Urgency.NOW ? config.dangerColor()
			: step.getUrgency() == Urgency.SOON ? config.waterColor() : Color.WHITE;
