				.right("Water " + plugin.getWater())
				.leftColor(MUTED)
				.rightColor(MUTED)
				.build());
		}
		return super.render(g);
	}
}

package com.toadfx.tithefarmautopilot.state;

import com.toadfx.tithefarmautopilot.logic.Reward;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.ObjectID;
import net.runelite.api.gameval.VarbitID;

/** Game IDs used by the plugin, all from RuneLite's gameval classes. */
public final class Ids
{
	public static final int[] SEEDS = {ItemID.HOSIDIUS_TITHE_SEED_A, ItemID.HOSIDIUS_TITHE_SEED_B, ItemID.HOSIDIUS_TITHE_SEED_C};
	public static final int[] FRUIT = {ItemID.HOSIDIUS_TITHE_FRUIT_A, ItemID.HOSIDIUS_TITHE_FRUIT_B, ItemID.HOSIDIUS_TITHE_FRUIT_C};
	public static final int FERTILISER = ItemID.HOSIDIUS_TITHE_FERTILISER;
	public static final int DIBBER = ItemID.DIBBER;
	public static final int SPADE = ItemID.SPADE;
	public static final int GRICOLLER_CAN = ItemID.ZEAH_WATERINGCAN;

	/** Watering cans by doses: index = doses (0..8). */
	public static final int[] CANS = {
		ItemID.WATERING_CAN_0, ItemID.WATERING_CAN_1, ItemID.WATERING_CAN_2, ItemID.WATERING_CAN_3,
		ItemID.WATERING_CAN_4, ItemID.WATERING_CAN_5, ItemID.WATERING_CAN_6, ItemID.WATERING_CAN_7,
		ItemID.WATERING_CAN_8,
	};

	public static final int[] OUTFIT = {
		ItemID.TITHE_REWARD_HAT_MALE, ItemID.TITHE_REWARD_HAT_FEMALE,
		ItemID.TITHE_REWARD_TORSO_MALE, ItemID.TITHE_REWARD_TORSO_FEMALE,
		ItemID.TITHE_REWARD_LEGS_MALE, ItemID.TITHE_REWARD_LEGS_FEMALE,
		ItemID.TITHE_REWARD_FEET_MALE, ItemID.TITHE_REWARD_FEET_FEMALE,
	};

	public static final int SACK = ObjectID.TITHE_SACK_OF_FRUIT;
	public static final int SACK_EMPTY = ObjectID.TITHE_SACK_OF_FRUIT_EMPTY;
	public static final int SEED_TABLE = ObjectID.TITHE_PLANT_SEED_TABLE;
	public static final int[] BARRELS = {ObjectID.FARM_WATER_BARREL1, ObjectID.FARM_WATER_BARREL2, ObjectID.WATER_BARREL1, ObjectID.WATER_BARREL2};

	/** Fruit deposited this session (the number on the farm's score box). */
	public static final int SCORE_VARBIT = VarbitID.HOSIDIUS_TITHE_SCORE;
	/** Tithe reward points to spend. */
	public static final int POINTS_VARBIT = VarbitID.HOSIDIUS_TITHE_REWARDPOINTS;
	public static final int GRICOLLER_CHARGES_VARBIT = VarbitID.ZEAH_WATERINGCAN_CHARGES;

	private Ids()
	{
	}

	/** Which planner reward an item proves you own, or null. */
	public static Reward rewardFor(int itemId)
	{
		switch (itemId)
		{
			case ItemID.ZEAH_WATERINGCAN:
				return Reward.GRICOLLERS_CAN;
			case ItemID.TITHE_REWARD_HAT_MALE:
			case ItemID.TITHE_REWARD_HAT_FEMALE:
				return Reward.FARMERS_HAT;
			case ItemID.TITHE_REWARD_TORSO_MALE:
			case ItemID.TITHE_REWARD_TORSO_FEMALE:
				return Reward.FARMERS_JACKET;
			case ItemID.TITHE_REWARD_LEGS_MALE:
			case ItemID.TITHE_REWARD_LEGS_FEMALE:
				return Reward.FARMERS_TROUSERS;
			case ItemID.TITHE_REWARD_FEET_MALE:
			case ItemID.TITHE_REWARD_FEET_FEMALE:
				return Reward.FARMERS_BOOTS;
			case ItemID.SEED_BOX:
			case ItemID.SEED_BOX_OPEN:
				return Reward.SEED_BOX;
			case ItemID.SLAYER_HERB_SACK:
			case ItemID.SLAYER_HERB_SACK_OPEN:
				return Reward.HERB_SACK;
			default:
				return null;
		}
	}

	public static boolean isBarrel(int objectId)
	{
		for (int id : BARRELS)
		{
			if (id == objectId)
			{
				return true;
			}
		}
		return false;
	}

	public static int cansDoses(int itemId)
	{
		for (int d = 0; d < CANS.length; d++)
		{
			if (CANS[d] == itemId)
			{
				return d;
			}
		}
		return -1;
	}

	public static int seedIndex(int[] list, int itemId)
	{
		for (int i = 0; i < list.length; i++)
		{
			if (list[i] == itemId)
			{
				return i;
			}
		}
		return -1;
	}

	public static boolean isOutfit(int itemId)
	{
		for (int id : OUTFIT)
		{
			if (id == itemId)
			{
				return true;
			}
		}
		return false;
	}
}

