/** Side panel: style and goal, next step, session, last lap, recent laps. */
public class TitheFarmAutopilotPanel extends PluginPanel
{
	private static final Color MAGENTA = new Color(0xFF, 0x00, 0xF1);
	private static final Color GOLD = new Color(0xFF, 0xEB, 0x00);
	private static final Color NOW = new Color(0xFF, 0x1E, 0x1E);
	private static final Color GOOD = new Color(0x00, 0xE6, 0x76);
	private static final Color BLUE = new Color(0x3F, 0xA9, 0xF5);
	private static final Color MUTED = ColorScheme.LIGHT_GRAY_COLOR;
	private static final int HISTORY_ROWS = 8;

	private final TitheFarmAutopilotPlugin plugin;
	private final TitheFarmAutopilotConfig config;
	private final ConfigManager configManager;

	private final JComboBox<PlayStyle> styleBox = new JComboBox<>(PlayStyle.values());
	private final JComboBox<Goal> goalBox = new JComboBox<>(Goal.values());
	private final JLabel styleNote = new JLabel();
	private final JLabel seedNote = new JLabel();
	private final JPanel planRows = new JPanel();
	private String planSignature = "";
	private final JLabel stepTitle = new JLabel();
	private final JLabel stepDetail = new JLabel();
	private final JPanel goalRows = new JPanel();
	private final JPanel sessionRows = new JPanel();
	private final JPanel lastRows = new JPanel();
	private final JPanel historyRows = new JPanel();
	private boolean syncing;

	public TitheFarmAutopilotPanel(TitheFarmAutopilotPlugin plugin, TitheFarmAutopilotConfig config, ConfigManager configManager, BufferedImage logo)
	{
		super(true);
		this.plugin = plugin;
		this.config = config;
		this.configManager = configManager;

		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		JPanel content = new JPanel();
		content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
		content.setBackground(ColorScheme.DARK_GRAY_COLOR);
		add(content, BorderLayout.NORTH);

		if (logo != null)
		{
			JLabel logoLabel = new JLabel(new ImageIcon(logo));
			logoLabel.setHorizontalAlignment(SwingConstants.CENTER);
			JPanel logoRow = new JPanel(new BorderLayout());
			logoRow.setBackground(ColorScheme.DARK_GRAY_COLOR);
			logoRow.add(logoLabel, BorderLayout.CENTER);
			logoRow.setBorder(new EmptyBorder(0, 0, 8, 0));
			content.add(logoRow);
		}

		content.add(section("Play style", settingsCard()));

		JPanel stepCard = card();
		stepTitle.setFont(FontManager.getRunescapeBoldFont());
		stepTitle.setForeground(MAGENTA);
		stepDetail.setFont(FontManager.getRunescapeSmallFont());
		stepDetail.setForeground(Color.WHITE);
		stepCard.add(stepTitle);
		stepCard.add(Box.createVerticalStrut(2));
		stepCard.add(stepDetail);
		content.add(section("Next step", stepCard));

		content.add(section("Points", rows(goalRows)));
		JPanel planCard = rows(planRows);
		content.add(section("Rewards planner", planCard));
		content.add(section("Session", rows(sessionRows)));
		content.add(section("Last lap", rows(lastRows)));
		content.add(section("Recent laps", rows(historyRows)));

		JButton reset = new JButton("Reset session");
		reset.setFocusPainted(false);
		reset.addActionListener(e -> plugin.resetSession());
		JPanel buttons = new JPanel(new GridLayout(1, 1));
		buttons.setBackground(ColorScheme.DARK_GRAY_COLOR);
		buttons.add(reset);
		buttons.setAlignmentX(Component.LEFT_ALIGNMENT);
		content.add(buttons);

		JLabel credit = new JLabel("Made by ToadFx");
		credit.setFont(FontManager.getRunescapeSmallFont());
		credit.setForeground(new Color(140, 140, 140));
		credit.setBorder(new EmptyBorder(8, 2, 0, 0));
		content.add(credit);
		if (config.showSocials())
		{
			JPanel socials = SocialLinks.row();
			socials.setBorder(new EmptyBorder(4, 0, 0, 0));
			content.add(socials);
		}

		refresh();
	}

	private JPanel settingsCard()
	{
		JPanel p = card();
		styleBox.setAlignmentX(Component.LEFT_ALIGNMENT);
		goalBox.setAlignmentX(Component.LEFT_ALIGNMENT);
		styleBox.addActionListener(e ->
		{
			if (!syncing && styleBox.getSelectedItem() != null)
			{
				configManager.setConfiguration(TitheFarmAutopilotConfig.GROUP, "playStyle", styleBox.getSelectedItem());
			}
		});
		goalBox.addActionListener(e ->
		{
			if (!syncing && goalBox.getSelectedItem() != null)
			{
				configManager.setConfiguration(TitheFarmAutopilotConfig.GROUP, "goal", goalBox.getSelectedItem());
			}
		});
		styleNote.setFont(FontManager.getRunescapeSmallFont());
		styleNote.setForeground(MUTED);
		styleNote.setAlignmentX(Component.LEFT_ALIGNMENT);
		p.add(small("Style"));
		p.add(styleBox);
		p.add(Box.createVerticalStrut(4));
		p.add(styleNote);
		p.add(Box.createVerticalStrut(6));
		seedNote.setFont(FontManager.getRunescapeSmallFont());
		seedNote.setForeground(GOOD);
		seedNote.setAlignmentX(Component.LEFT_ALIGNMENT);
		p.add(seedNote);
		p.add(Box.createVerticalStrut(6));
		p.add(small("Saving for"));
		p.add(goalBox);
		return p;
	}

	/** Called on the Swing thread. */
	public void refresh()
	{
		syncing = true;
		styleBox.setSelectedItem(config.playStyle());
		goalBox.setSelectedItem(config.goal());
		syncing = false;
		int plants = plugin.getFarm().size();
		styleNote.setText(html(config.playStyle().description() + ". " + plants + " plants a lap."));
		String seed = plugin.getSeedAdvice();
		seedNote.setText(html(seed.isEmpty()
			? (plugin.getFarmingLevel() > 0 ? "You need 34 Farming for Tithe Farm (you have " + plugin.getFarmingLevel() + ")" : "Log in to see which seed to take")
			: seed));

		Instruction step = plugin.getInstruction();
		stepTitle.setText(html(step.isEmpty() ? "Head to the Tithe Farm (Hosidius)" : step.getTitle()));
		stepTitle.setForeground(step.getUrgency() == Urgency.NOW ? NOW : step.getUrgency() == Urgency.SOON ? GOLD : MAGENTA);
		stepDetail.setText(html(step.getDetail()));

		long now = System.currentTimeMillis();
		goalRows.removeAll();
		int points = plugin.getPoints();
		if (points < 0)
		{
			addRow(goalRows, "Points show once you're at the farm", "", MUTED);
		}
		else
		{
			addRow(goalRows, "Points", QuantityFormatter.formatNumber(points), Color.WHITE);
			int target = plugin.getGoalTarget();
			if (target > 0)
			{
				int left = target - points;
				addRow(goalRows, "Next: " + plugin.getGoalName(), left <= 0 ? "ready!" : left + " pts", left <= 0 ? GOOD : Color.WHITE);
				if (left > 0)
				{
					addRow(goalRows, "Laps left (" + plants + " plants)", String.valueOf(Rewards.lapsFor(left, plants)), MUTED);
				}
			}
		}
		refreshPlan();

		sessionRows.removeAll();
		Session s = plugin.getSession();
		if (!s.isStarted())
		{
			addRow(sessionRows, "Starts when you plant", "", MUTED);
		}
		else
		{
			addRow(sessionRows, "Laps", String.valueOf(s.getLaps()), Color.WHITE);
			addRow(sessionRows, "Fruit harvested", String.valueOf(s.getHarvested()), Color.WHITE);
			addRow(sessionRows, "Plants lost", String.valueOf(s.getDeaths()), s.getDeaths() > 0 ? NOW : Color.WHITE);
			addRow(sessionRows, "Farming XP", QuantityFormatter.quantityToStackSize(s.getXp()), Color.WHITE);
			addRow(sessionRows, "XP/hr", QuantityFormatter.quantityToStackSize(s.perHour(s.getXp(), now)), GOOD);
			addRow(sessionRows, "Points gained", String.valueOf(s.getPoints()), Color.WHITE);
			addRow(sessionRows, "Points/hr", String.valueOf(s.perHour(s.getPoints(), now)), GOOD);
			if (s.getBestLapSeconds() > 0)
			{
				addRow(sessionRows, "Best clean lap", clock(s.getBestLapSeconds()), MAGENTA);
			}
		}

		lastRows.removeAll();
		LapRecord last = plugin.getLastLap();
		if (last == null)
		{
			addRow(lastRows, "No lap yet", "", MUTED);
		}
		else
		{
			addRow(lastRows, "Grade", last.grade, gradeColor(last.grade));
			addRow(lastRows, "Time", last.time(), Color.WHITE);
			addRow(lastRows, "Harvested", last.harvested + "/" + last.plants, Color.WHITE);
			if (last.deaths > 0)
			{
				addRow(lastRows, "Died", String.valueOf(last.deaths), NOW);
			}
			JLabel tip = small(html(last.tip));
			lastRows.add(tip);
		}

		historyRows.removeAll();
		List<LapRecord> history = plugin.getHistory();
		if (history.isEmpty())
		{
			addRow(historyRows, "None yet", "", MUTED);
		}
		else
		{
			for (int i = history.size() - 1, shown = 0; i >= 0 && shown < HISTORY_ROWS; i--, shown++)
			{
				LapRecord r = history.get(i);
				addRow(historyRows, r.grade + "  " + r.style + " " + r.plants, r.time() + (r.deaths > 0 ? "  -" + r.deaths : ""), gradeColor(r.grade));
			}
		}

		revalidate();
		repaint();
	}

	/** Rebuilds the planner rows only when something changed, so the tick boxes stay clickable. */
	private void refreshPlan()
	{
		List<RewardPlan.Row> plan = plugin.getRewardPlan();
		double pph = plugin.getPointsPerHour();
		StringBuilder sig = new StringBuilder();
		for (RewardPlan.Row r : plan)
		{
			sig.append(r.reward).append(r.status).append(r.pointsLeft).append(r.minutesLeft).append(';');
		}
		if (sig.toString().equals(planSignature))
		{
			return;
		}
		planSignature = sig.toString();
		planRows.removeAll();

		if (plan.isEmpty())
		{
			addRow(planRows, "Log in to plan your rewards", "", MUTED);
			return;
		}
		boolean first = true;
		for (RewardPlan.Row r : plan)
		{
			planRows.add(planRow(r, first));
			first = false;
		}
		int left = RewardPlan.pointsLeftForAll(plan);
		planRows.add(Box.createVerticalStrut(4));
		if (left > 0)
		{
			addRow(planRows, "Everything left", left + " pts", Color.WHITE);
			if (pph > 0)
			{
				addRow(planRows, "At ~" + (int) Math.round(pph) + " pts/hr", hours(left / pph), MUTED);
			}
		}
		else if (RewardPlan.next(plan) == null)
		{
			addRow(planRows, "Plan complete!", "", GOOD);
		}
		JLabel help = small(html("Tick what you own (found automatically in your bag, gear and bank). ▲ moves a reward up."));
		help.setBorder(new EmptyBorder(4, 0, 4, 0));
		planRows.add(help);
		JButton reset = new JButton("Reset order");
		reset.setFocusPainted(false);
		reset.setAlignmentX(Component.LEFT_ALIGNMENT);
		reset.addActionListener(e -> plugin.resetRewardOrder());
		planRows.add(reset);
	}

	private JPanel planRow(RewardPlan.Row r, boolean first)
	{
		JPanel row = new JPanel(new BorderLayout(4, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.setBorder(new EmptyBorder(1, 0, 1, 0));

		JCheckBox box = new JCheckBox();
		box.setSelected(r.status == RewardPlan.Status.OWNED);
		box.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		box.setToolTipText("I own this");
		box.addActionListener(e -> plugin.toggleOwned(r.reward));
		row.add(box, BorderLayout.WEST);

		JPanel text = new JPanel();
		text.setLayout(new BoxLayout(text, BoxLayout.Y_AXIS));
		text.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		JLabel name = new JLabel(r.reward.displayName() + "  " + r.reward.cost());
		name.setFont(FontManager.getRunescapeSmallFont());
		name.setToolTipText(r.reward.note());
		JLabel status = new JLabel(statusText(r));
		status.setFont(FontManager.getRunescapeSmallFont());
		switch (r.status)
		{
			case OWNED:
				name.setForeground(MUTED);
				status.setForeground(MUTED);
				break;
			case BUY_NOW:
				name.setForeground(Color.WHITE);
				status.setForeground(GOOD);
				break;
			case LOCKED:
				name.setForeground(MUTED);
				status.setForeground(NOW);
				break;
			default:
				name.setForeground(Color.WHITE);
				status.setForeground(GOLD);
				break;
		}
		text.add(name);
		text.add(status);
		row.add(text, BorderLayout.CENTER);

		JButton up = new JButton("▲");
		up.setFocusPainted(false);
		up.setMargin(new java.awt.Insets(0, 4, 0, 4));
		up.setEnabled(!first);
		up.setToolTipText("Move up");
		up.addActionListener(e -> plugin.moveRewardUp(r.reward));
		row.add(up, BorderLayout.EAST);
		return row;
	}

	private static String statusText(RewardPlan.Row r)
	{
		switch (r.status)
		{
			case OWNED:
				return "Owned";
			case BUY_NOW:
				return "Buy now!";
			case LOCKED:
				return "Needs " + r.reward.herbloreNeeded() + " Herblore";
			default:
				return r.pointsLeft + " pts · " + r.lapsLeft + " laps" + (r.minutesLeft >= 0 ? " · " + hours(r.minutesLeft / 60.0) : "");
		}
	}

	private static String hours(double h)
	{
		int minutes = (int) Math.ceil(h * 60);
		return minutes < 60 ? "~" + minutes + "m" : "~" + minutes / 60 + "h " + minutes % 60 + "m";
	}

	private static String clock(int seconds)
	{
		return seconds / 60 + ":" + String.format("%02d", seconds % 60);
	}

	private static Color gradeColor(String grade)
	{
		switch (grade)
		{
			case "S":
				return MAGENTA;
			case "A":
				return GOOD;
			case "B":
				return BLUE;
			case "C":
				return GOLD;
			case "D":
				return new Color(255, 140, 60);
			default:
				return NOW;
		}
	}

	private static String html(String s)
	{
		return "<html><body style='width:150px'>" + s.replace("&", "&amp;").replace("<", "&lt;") + "</body></html>";
	}

	private static JLabel small(String text)
	{
		JLabel l = new JLabel(text);
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(MUTED);
		l.setAlignmentX(Component.LEFT_ALIGNMENT);
		return l;
	}

	private static JPanel card()
	{
		JPanel p = new JPanel();
		p.setLayout(new BoxLayout(p, BoxLayout.Y_AXIS));
		p.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		p.setBorder(new EmptyBorder(6, 8, 6, 8));
		return p;
	}

	private static JPanel rows(JPanel inner)
	{
		inner.setLayout(new BoxLayout(inner, BoxLayout.Y_AXIS));
		inner.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		inner.setBorder(new EmptyBorder(6, 8, 6, 8));
		return inner;
	}

	private static JPanel section(String title, JPanel body)
	{
		JPanel wrap = new JPanel(new BorderLayout());
		wrap.setBackground(ColorScheme.DARK_GRAY_COLOR);
		wrap.setBorder(new EmptyBorder(0, 0, 8, 0));
		JLabel label = new JLabel(title);
		label.setFont(FontManager.getRunescapeBoldFont());
		label.setForeground(Color.WHITE);
		label.setBorder(new EmptyBorder(0, 2, 3, 0));
		wrap.add(label, BorderLayout.NORTH);
		wrap.add(body, BorderLayout.CENTER);
		return wrap;
	}

	private static void addRow(JPanel panel, String left, String right, Color rightColor)
	{
		JPanel row = new JPanel(new BorderLayout());
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		JLabel l = new JLabel(left);
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(right.isEmpty() ? rightColor : MUTED);
		JLabel r = new JLabel(right);
		r.setFont(FontManager.getRunescapeSmallFont());
		r.setForeground(rightColor);
		row.add(l, BorderLayout.WEST);
		row.add(r, BorderLayout.EAST);
		panel.add(row);
	}
}

package com.toadfx.tithefarmautopilot;

import com.toadfx.tithefarmautopilot.coach.Grader;
import com.toadfx.tithefarmautopilot.coach.LapRecord;
import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class CoachTest
{
	@Test
	public void grades()
	{
		int target = Grader.targetSeconds(20, false);
		assertEquals(255, target);
		assertEquals("S", Grader.grade(20, 20, 0, 250, false));
		assertEquals("A", Grader.grade(20, 20, 0, 280, false));
		assertEquals("B", Grader.grade(20, 20, 1, 280, false));
		assertEquals("F", Grader.grade(20, 15, 5, 250, false));
		assertEquals("F", Grader.grade(10, 0, 0, 250, false));
	}

	@Test
	public void lapRecordRoundTrip()
	{
		LapRecord r = new LapRecord(123L, "Steady", 20, 19, 1, 271, "B", "a|tip");
		LapRecord back = LapRecord.decode(r.encode());
		assertEquals("Steady", back.style);
		assertEquals(19, back.harvested);
		assertEquals("4:31", back.time());
		assertEquals("atip", back.tip);
	}
}

package com.toadfx.tithefarmautopilot;

import com.toadfx.tithefarmautopilot.logic.PlotIds;
import com.toadfx.tithefarmautopilot.logic.PlotKind;
import static org.junit.Assert.assertEquals;
import net.runelite.api.gameval.ObjectID;
import org.junit.Test;

/** Checks PlotIds' numbers against RuneLite's gameval names (runs in GitHub Actions). */
public class IdsTest
{
	@Test
	public void numbersMatchGameval()
	{
		assertEquals(ObjectID.HOSIDIUS_TITHE_EMPTY, PlotIds.EMPTY);
		assertEquals(ObjectID.HOSIDIUS_TITHE_A_1_DRY, PlotIds.FIRST);
		assertEquals(ObjectID.HOSIDIUS_TITHE_C_4_DEAD, PlotIds.LAST);
	}

	@Test
	public void everyNamedStateDecodes()
	{
		check(ObjectID.HOSIDIUS_TITHE_A_1_DRY, PlotKind.DRY, 1, 0);
		check(ObjectID.HOSIDIUS_TITHE_A_2_WET, PlotKind.WET, 2, 0);
		check(ObjectID.HOSIDIUS_TITHE_A_4, PlotKind.GROWN, 4, 0);
		check(ObjectID.HOSIDIUS_TITHE_B_3_DEAD, PlotKind.DEAD, 3, 1);
		check(ObjectID.HOSIDIUS_TITHE_B_1_WET, PlotKind.WET, 1, 1);
		check(ObjectID.HOSIDIUS_TITHE_C_3_DRY, PlotKind.DRY, 3, 2);
		check(ObjectID.HOSIDIUS_TITHE_C_4, PlotKind.GROWN, 4, 2);
		check(ObjectID.HOSIDIUS_TITHE_C_4_DEAD, PlotKind.DEAD, 4, 2);
	}

	private static void check(int id, PlotKind kind, int stage, int seed)
	{
		PlotIds.Decoded d = PlotIds.decode(id);
		assertEquals(kind, d.kind);
		assertEquals(stage, d.stage);
		assertEquals(seed, d.seed);
	}
}

