		assertEquals(Action.PLANT, i.getAction());
		assertEquals(0, i.getTarget());

		f.apply(f.getRoute().get(0), PlotKind.DRY, 1, 5);
		i = Planner.next(f.getRoute(), f.getCursor(), s, PlayStyle.STEADY, true);
		assertEquals(Action.WATER, i.getAction());
		assertEquals(0, i.getTarget());

		f.apply(f.getRoute().get(0), PlotKind.WET, 1, 7);
		i = Planner.next(f.getRoute(), f.getCursor(), s, PlayStyle.STEADY, true);
		assertEquals(Action.PLANT, i.getAction());
		assertEquals(1, i.getTarget());
	}

