	{
		Farm f = seen(20, 100);
		Snapshot s = ready();
		f.apply(f.getRoute().get(3), PlotKind.DRY, 1, 0);
		f.apply(f.getRoute().get(4), PlotKind.DRY, 1, 30);
		s.tick = 85;
		Instruction i = Planner.next(f.getRoute(), 4, s, PlayStyle.STEADY, true);
		assertEquals(Action.WATER, i.getAction());
		assertEquals(3, i.getTarget());
		assertEquals(Urgency.NOW, i.getUrgency());
	}

