		Snapshot s = ready();
		s.fruit = 20;
		assertEquals(Action.DEPOSIT, Planner.next(f.getRoute(), -1, s, PlayStyle.STEADY, true).getAction());
		s.fruit = 0;
		s.water = 10;
		assertEquals(Action.FILL_CANS, Planner.next(f.getRoute(), -1, s, PlayStyle.STEADY, true).getAction());
		s.water = 60;
		s.seeds = 0;
		assertEquals(Action.GET_SEEDS, Planner.next(f.getRoute(), -1, s, PlayStyle.STEADY, true).getAction());
		s.seeds = 50;
		s.canPlant = false;
		assertEquals(Action.GET_TOOLS, Planner.next(f.getRoute(), -1, s, PlayStyle.STEADY, true).getAction());
	}

