	public void comboReplantsRightAfterHarvest()
	{
		Farm f = seen(PlayStyle.COMBO_20, 20);
		Snapshot s = ready();
		for (Plot p : f.getRoute())
		{
			f.apply(p, PlotKind.DRY, 1, 0);
			f.apply(p, PlotKind.WET, 3, 0);
		}
		f.apply(f.getRoute().get(0), PlotKind.GROWN, 4, 300);
		s.tick = 300;
		assertEquals(Action.HARVEST, Planner.next(f.getRoute(), f.getCursor(), s, PlayStyle.COMBO_20, false).getAction());
		f.apply(f.getRoute().get(0), PlotKind.EMPTY, 0, 302);
		Instruction i = Planner.next(f.getRoute(), f.getCursor(), s, PlayStyle.COMBO_20, false);
		assertEquals(Action.PLANT, i.getAction());
