	@Test
	public void staggeredKeepsGroupsSpacedApart()
	{
		Farm f = seen(PlayStyle.STAGGERED, 24);
		Snapshot s = ready();
		s.tick = 10;
		// Group A (patches 1-4) in stage 1: group B may still go in.
		for (int i = 0; i < 4; i++)
		{
			f.apply(f.getRoute().get(i), PlotKind.DRY, 1, 0);
			f.apply(f.getRoute().get(i), PlotKind.WET, 1, 1);
		}
		Instruction i = Planner.next(f.getRoute(), 3, s, PlayStyle.STAGGERED, false);
		assertEquals(Action.PLANT, i.getAction());
		assertEquals(4, i.getTarget());
		// Groups A and B both in stage 1: group C waits.
		for (int k = 4; k < 8; k++)
		{
			f.apply(f.getRoute().get(k), PlotKind.DRY, 1, 5);
			f.apply(f.getRoute().get(k), PlotKind.WET, 1, 6);
		}
		assertEquals(Action.WAIT, Planner.next(f.getRoute(), 7, s, PlayStyle.STAGGERED, false).getAction());
	}

