		simulate(PlayStyle.COMBO_20, 20, 100, 5, false);
	}

	private static void simulate(PlayStyle style, int plants, int stageTicks, int actionTicks)
	{
		simulate(style, plants, stageTicks, actionTicks, true);
	}

	/**
	 * Plays laps by doing exactly what the planner says, with each action taking {@code actionTicks}
	 * (walk + click + animation), and the game growing plants on its own clock. Every plant should
	 * survive and every lap should finish.
	 */
	private static void simulate(PlayStyle style, int plants, int stageTicks, int actionTicks, boolean full)
	{
		Farm f = seen(style, plants);
		Snapshot s = ready();
		s.water = 3 * plants;
		int[] stageStart = new int[plants];
		boolean[] fertilised = new boolean[plants];
		List<Farm.Lap> laps = new ArrayList<>();
		int busy = 0;
		for (int tick = 1; tick < 12000 && laps.size() < 3; tick++)
		{
			s.tick = tick;
			// The game: stages end on their own clock.
			for (Plot p : f.getRoute())
			{
				int len = fertilised[p.index] ? 50 : 100;
				if (p.isGrowing() && tick - stageStart[p.index] >= len)
				{
					if (p.getKind() == PlotKind.DRY)
					{
						f.apply(p, PlotKind.DEAD, p.getStage(), tick);
					}
					else if (p.getStage() < 3)
					{
						f.apply(p, PlotKind.DRY, p.getStage() + 1, tick);
						stageStart[p.index] = tick;
					}
					else
					{
						f.apply(p, PlotKind.GROWN, 4, tick);
					}
				}
			}
			Farm.Lap lap = f.takeFinishedLap();
			if (lap != null)
			{
				laps.add(lap);
			}
			if (busy > 0)
			{
				busy--;
				continue;
			}
			// The player: do the step.
			Instruction i = Planner.next(f.getRoute(), f.getCursor(), s, style, false);
			Plot t = i.getTarget() >= 0 ? f.getRoute().get(i.getTarget()) : null;
			switch (i.getAction())
			{
				case PLANT:
					f.apply(t, PlotKind.DRY, 1, tick);
					stageStart[t.index] = tick;
					fertilised[t.index] = false;
					s.seeds--;
					busy = actionTicks;
					break;
				case WATER:
					f.apply(t, PlotKind.WET, t.getStage(), tick);
					s.water--;
					busy = actionTicks;
					break;
				case FERTILISE:
					// The real game halves what's left of the stage; the sim restarts a short stage.
					fertilised[t.index] = true;
					stageStart[t.index] = Math.max(stageStart[t.index], tick - 50 + (100 - (tick - stageStart[t.index])) / 2);
					t.markFertilised(tick);
					busy = actionTicks;
					break;
				case HARVEST:
					f.apply(t, PlotKind.EMPTY, 0, tick);
					s.fruit++;
					busy = actionTicks;
					break;
				case CLEAR:
					f.apply(t, PlotKind.EMPTY, 0, tick);
					busy = actionTicks;
					break;
				case DEPOSIT:
					s.fruit = 0;
					busy = 8;
					break;
				case FILL_CANS:
					s.water = 3 * plants;
					busy = 15;
					break;
				case WAIT:
				case NONE:
					break;
				default:
					throw new AssertionError("Unexpected step " + i);
			}
		}
		assertEquals(style + " " + plants + ": laps finished", 3, laps.size());
		for (Farm.Lap lap : laps)
		{
			assertEquals(style + " " + plants + ": deaths", 0, lap.deaths);
			assertEquals(style + " " + plants + ": harvested what was planted", lap.planted, lap.harvested);
			if (full)
			{
				assertEquals(style + " " + plants + ": planted the whole route", plants, lap.planted);
			}
			assertTrue(lap.seconds() > 0);
		}
	}
}

package com.toadfx.tithefarmautopilot;

import com.toadfx.tithefarmautopilot.logic.Plot;
import com.toadfx.tithefarmautopilot.logic.PlotIds;
import com.toadfx.tithefarmautopilot.logic.PlotKind;
import com.toadfx.tithefarmautopilot.logic.Route;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import org.junit.Test;

public class PlotTest
{
	@Test
	public void decodesTheIdRun()
	{
		assertEquals(PlotKind.EMPTY, PlotIds.decode(27383).kind);
		assertEquals(PlotKind.DRY, PlotIds.decode(27384).kind);
		assertEquals(PlotKind.WET, PlotIds.decode(27385).kind);
		assertEquals(PlotKind.DEAD, PlotIds.decode(27386).kind);
		assertEquals(2, PlotIds.decode(27387).stage);
		assertEquals(PlotKind.GROWN, PlotIds.decode(27393).kind);
		assertEquals(PlotKind.DRY, PlotIds.decode(27406).kind);
		assertEquals(2, PlotIds.decode(27406).seed);
		assertEquals(PlotKind.GROWN, PlotIds.decode(27415).kind);
		assertNull(PlotIds.decode(27417));
		assertNull(PlotIds.decode(27382));
	}

	@Test
	public void lifecycleAndTimer()
	{
		Plot p = new Plot(0, 34, 57);
		assertEquals(Plot.Change.FIRST_SEEN, p.update(PlotKind.EMPTY, 0, 0));
		assertEquals(Plot.Change.PLANTED, p.update(PlotKind.DRY, 1, 10));
		assertEquals(100, p.ticksLeft(10));
		assertEquals(3, p.wateringsLeft());
		assertEquals(Plot.Change.WATERED, p.update(PlotKind.WET, 1, 12));
		// Watering doesn't restart the stage clock.
		assertEquals(98, p.ticksLeft(12));
		assertEquals(2, p.wateringsLeft());
		assertEquals(Plot.Change.NEW_STAGE, p.update(PlotKind.DRY, 2, 110));
		assertEquals(100, p.ticksLeft(110));
		p.update(PlotKind.WET, 2, 115);
		p.update(PlotKind.DRY, 3, 210);
		p.update(PlotKind.WET, 3, 215);
		assertEquals(0, p.wateringsLeft());
		assertEquals(Plot.Change.GREW, p.update(PlotKind.GROWN, 4, 310));
		assertEquals(-1, p.ticksLeft(310));
		assertEquals(Plot.Change.HARVESTED, p.update(PlotKind.EMPTY, 0, 320));
	}

	@Test
	public void learnsFertilisedStageLength()
	{
		Plot p = new Plot(0, 34, 57);
		p.update(PlotKind.EMPTY, 0, 0);
		p.update(PlotKind.DRY, 1, 0);
		p.update(PlotKind.WET, 1, 2);
		p.update(PlotKind.DRY, 2, 50);
		assertEquals(Plot.FAST_STAGE_TICKS, p.getStageTicks());
		assertEquals(50, p.ticksLeft(50));
	}

	@Test
	public void death()
	{
		Plot p = new Plot(0, 34, 57);
		p.update(PlotKind.EMPTY, 0, 0);
		p.update(PlotKind.DRY, 1, 0);
		assertEquals(Plot.Change.DIED, p.update(PlotKind.DEAD, 1, 100));
		assertEquals(Plot.Change.CLEARED, p.update(PlotKind.EMPTY, 0, 110));
	}

	@Test
	public void routeIsTheWikiBasic20()
	{
		assertEquals(0, Route.indexOf(Route.BASIC_20, 34, 57, 20));
		assertEquals(19, Route.indexOf(Route.BASIC_20, 29, 57, 20));
		assertEquals(-1, Route.indexOf(Route.BASIC_20, 29, 57, 10));
		assertEquals(-1, Route.indexOf(Route.BASIC_20, 19, 33, 20));
		assertEquals(12, Route.build(Route.BASIC_20, 12).size());
		assertEquals(20, Route.build(Route.BASIC_20, 99).size());
	}

	@Test
	public void everyRouteUsesRealPatchesOnce()
	{
		for (com.toadfx.tithefarmautopilot.logic.PlayStyle style : com.toadfx.tithefarmautopilot.logic.PlayStyle.values())
		{
			int[] r = style.route();
			java.util.Set<Integer> seen = new java.util.HashSet<>();
			for (int i = 0; i < r.length; i += 2)
			{
				org.junit.Assert.assertTrue(style + " patch " + r[i] + "," + r[i + 1], Route.isPatch(r[i], r[i + 1]));
				org.junit.Assert.assertTrue(style + " repeats " + r[i] + "," + r[i + 1], seen.add(r[i] * 100 + r[i + 1]));
			}
		}
		assertEquals(20, Route.COMBO_20.length / 2);
		assertEquals(23, Route.SIMPLE_23.length / 2);
		assertEquals(25, Route.R25X4.length / 2);
		assertEquals(24, Route.R24X.length / 2);
		assertEquals(25, Route.R25_EASY.length / 2);
		assertEquals(25, Route.R25_RECURSIVE.length / 2);
		assertEquals(24, Route.R24_COMBO.length / 2);
	}

	@Test
	public void fertiliserHalvesTheRestOfTheStage()
	{
		Plot p = new Plot(0, 34, 57);
		p.update(PlotKind.EMPTY, 0, 0);
		p.update(PlotKind.DRY, 1, 0);
		p.update(PlotKind.WET, 1, 2);
		p.markFertilised(10);
		// 90 ticks were left, now 45.
		assertEquals(45, p.ticksLeft(10));
		org.junit.Assert.assertTrue(p.isFertilised());
		p.update(PlotKind.DRY, 2, 55);
		assertEquals(50, p.ticksLeft(55));
		p.update(PlotKind.WET, 2, 56);
		p.update(PlotKind.DRY, 3, 105);
		p.update(PlotKind.WET, 3, 106);
		p.update(PlotKind.GROWN, 4, 155);
		p.update(PlotKind.EMPTY, 0, 160);
		org.junit.Assert.assertFalse(p.isFertilised());
	}
}

package com.toadfx.tithefarmautopilot;

import com.toadfx.tithefarmautopilot.logic.Reward;
import com.toadfx.tithefarmautopilot.logic.RewardPlan;
import com.toadfx.tithefarmautopilot.logic.Rewards;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.EnumSet;
import java.util.List;
import java.util.Set;
import org.junit.Test;

public class RewardPlanTest
{
	@Test
	public void totalMatchesWiki()
	{
		// "All untradeable rewards and unlocks total 1,150 points" (OSRS Wiki)
		assertEquals(1150, Reward.total());
		assertEquals(Reward.values().length, RewardPlan.DEFAULT_ORDER.size());
	}

	@Test
	public void runningTotalsSkipOwned()
	{
		Set<Reward> owned = EnumSet.of(Reward.GRICOLLERS_CAN);
		List<RewardPlan.Row> rows = RewardPlan.plan(RewardPlan.DEFAULT_ORDER, owned, 160, 99, 20, 0);
		assertEquals(RewardPlan.Status.OWNED, rows.get(0).status);
		// Jacket 150: affordable with 160
		assertEquals(Reward.FARMERS_JACKET, rows.get(1).reward);
		assertEquals(RewardPlan.Status.BUY_NOW, rows.get(1).status);
		// Trousers: 150 + 125 = 275, 115 short
		assertEquals(275, rows.get(2).cumulative);
		assertEquals(115, rows.get(2).pointsLeft);
		assertEquals(Rewards.fruitFor(115), rows.get(2).fruitLeft);
		assertEquals(Rewards.lapsFor(115, 20), rows.get(2).lapsLeft);
		assertEquals(-1, rows.get(2).minutesLeft);
		assertEquals(Reward.FARMERS_JACKET, RewardPlan.next(rows).reward);
		assertEquals(1150 - 200 - 160, RewardPlan.pointsLeftForAll(rows));
	}

	@Test
	public void herbSackLockedBelow58Herblore()
	{
		List<RewardPlan.Row> rows = RewardPlan.plan(RewardPlan.DEFAULT_ORDER, EnumSet.noneOf(Reward.class), 0, 40, 20, 100);
		RewardPlan.Row sack = null;
		for (RewardPlan.Row r : rows)
		{
			if (r.reward == Reward.HERB_SACK)
			{
				sack = r;
			}
		}
		assertEquals(RewardPlan.Status.LOCKED, sack.status);
		// Locked rewards don't count towards the total.
		assertEquals(1150 - 250, RewardPlan.pointsLeftForAll(rows));
	}

	@Test
	public void minutesFromRate()
	{
		List<RewardPlan.Row> rows = RewardPlan.plan(List.of(Reward.GRICOLLERS_CAN), EnumSet.noneOf(Reward.class), 0, 99, 20, 100);
		assertEquals(120, rows.get(0).minutesLeft);
		// 20 plants in a 300 s lap = 7 points a lap, 84 an hour
		assertEquals(84.0, RewardPlan.estimatePointsPerHour(20, 300), 0.01);
	}

	@Test
	public void planDone()
	{
		List<RewardPlan.Row> rows = RewardPlan.plan(RewardPlan.DEFAULT_ORDER, EnumSet.allOf(Reward.class), 50, 99, 20, 0);
		assertNull(RewardPlan.next(rows));
		assertEquals(0, RewardPlan.pointsLeftForAll(rows));
	}

	@Test
	public void saveAndReorder()
	{
		List<Reward> moved = RewardPlan.moveUp(RewardPlan.DEFAULT_ORDER, Reward.SEED_BOX);
		assertEquals(Reward.SEED_BOX, moved.get(4));
		List<Reward> back = RewardPlan.decodeOrder(RewardPlan.encodeOrder(moved));
		assertEquals(moved, back);
		// Unknown names dropped, missing rewards added on the end.
		List<Reward> partial = RewardPlan.decodeOrder("AUTO_WEED,NOPE");
		assertEquals(Reward.AUTO_WEED, partial.get(0));
		assertEquals(Reward.values().length, partial.size());
		Set<Reward> owned = RewardPlan.decodeOwned(RewardPlan.encodeOwned(EnumSet.of(Reward.SEED_BOX, Reward.AUTO_WEED)));
		assertTrue(owned.contains(Reward.SEED_BOX) && owned.contains(Reward.AUTO_WEED) && owned.size() == 2);
		assertTrue(RewardPlan.decodeOwned(null).isEmpty());
	}
}

package com.toadfx.tithefarmautopilot;

import com.toadfx.tithefarmautopilot.logic.Rewards;
import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class RewardsTest
{
	@Test
	public void wikiPoints()
	{
		// 1 per 3 fruit + 2 per 100: a full 100 = 35 (OSRS Wiki)
		assertEquals(35, Rewards.points(100));
		assertEquals(0, Rewards.points(2));
		assertEquals(1, Rewards.points(3));
		assertEquals(70, Rewards.points(200));
	}

	@Test
	public void wikiFullSackXp()
	{
		assertEquals(9660, Rewards.fullSackXp(0), 0.01);
		assertEquals(22540, Rewards.fullSackXp(1), 0.01);
		assertEquals(37030, Rewards.fullSackXp(2), 0.01);
	}

	@Test
	public void fruitAndLapsForGoal()
	{
		assertEquals(100, Rewards.fruitFor(35));
		assertEquals(Rewards.points(Rewards.fruitFor(200)) >= 200, true);
		assertEquals(Rewards.points(Rewards.fruitFor(200) - 1) < 200, true);
		// Gricoller's can: 200 points at 20 plants a lap
		assertEquals((int) Math.ceil(Rewards.fruitFor(200) / 20.0), Rewards.lapsFor(200, 20));
		assertEquals(0, Rewards.lapsFor(0, 20));
	}

	@Test
	public void seedsAndBonus()
	{
		assertEquals(-1, Rewards.bestSeed(33));
		assertEquals(0, Rewards.bestSeed(34));
		assertEquals(1, Rewards.bestSeed(73));
		assertEquals(2, Rewards.bestSeed(99));
		assertEquals(75, Rewards.toBonus(0));
		assertEquals(1, Rewards.toBonus(74));
		assertEquals(0, Rewards.toBonus(80));
		assertEquals(75, Rewards.toBonus(100));
	}
}

